import { expect, test } from "bun:test"
import type { AgentRelayState } from "../src/shared/protocol"
import { installChrome, settle, type StubEvent } from "./chrome-stub"

// The bundled pairing file (relay-pairing.json, written into an unpacked build by `install`) is looked for again
// while the extension is unpaired, and re-read on Reconnect and when the stored code changes. No relay: WebSocket is
// a fake that never opens unless told to. The fakes stay installed after this file: the relay it creates keeps its
// timers for the rest of the run, and must never reach a real port.

const stub = installChrome()
;(globalThis as { __OPENCODE_BROWSER_BUILD__?: string }).__OPENCODE_BROWSER_BUILD__ = "test"

class FakeWebSocket {
  static readonly CONNECTING = 0
  static readonly OPEN = 1
  static readonly CLOSING = 2
  static readonly CLOSED = 3
  static readonly made: FakeWebSocket[] = []
  readyState = FakeWebSocket.CONNECTING
  onopen: ((event: unknown) => void) | null = null
  onmessage: ((event: unknown) => void) | null = null
  onclose: ((event: unknown) => void) | null = null
  constructor(readonly url: string) {
    FakeWebSocket.made.push(this)
  }
  send() {}
  close(code = 1006, reason = "") {
    if (this.readyState === FakeWebSocket.CLOSED) return
    this.readyState = FakeWebSocket.CLOSED
    queueMicrotask(() => this.onclose?.({ code, reason, wasClean: false }))
  }
}

const CODE = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
const OTHER = "ZYXWVTSRQPNMKJHGFEDCBA9876543210"
let bundled: string | undefined
const reads: string[] = []
const realFetch = globalThis.fetch
globalThis.fetch = (async (input: string | URL) => {
  const url = String(input)
  if (!url.endsWith("/relay-pairing.json")) return realFetch(input)
  reads.push(url)
  return bundled === undefined ? new Response("not found", { status: 404 }) : Response.json({ code: bundled })
}) as typeof fetch
;(globalThis as { WebSocket: unknown }).WebSocket = FakeWebSocket

await stub.chrome.storage.local.set({ agentRelayPort: 19925 })
const { createAgentRelay } = await import("../src/background/agent-relay")
const states: AgentRelayState[] = []
const relay = createAgentRelay({ changed: (state) => states.push(state), badgesChanged: () => {} })
const until = async (check: () => boolean) => {
  for (let i = 0; i < 100 && !check(); i++) await settle()
  expect(check()).toBe(true)
}
const alarm = () => (chrome.alarms.onAlarm as unknown as StubEvent).emit({ name: "opencode-browser-relay" })

test("without a pairing file, the extension waits unpaired and doesn't connect", async () => {
  await until(() => relay.state().status === "unpaired")
  expect(relay.state().pairing).toBe("none")
  expect(FakeWebSocket.made).toHaveLength(0)
  expect(reads.length).toBeGreaterThan(0)
})

test("a pairing file written later (bun run setup) is found on the next attempt, without a worker restart", async () => {
  const before = reads.length
  bundled = CODE
  alarm()
  await until(() => FakeWebSocket.made.length === 1)
  expect(reads.length).toBe(before + 1)
  expect(relay.state().pairing).toBe("bundled")
  expect(FakeWebSocket.made[0]!.url).toBe("ws://127.0.0.1:19925/extension")
})

test("a found file is cached between attempts, and read again on Reconnect", async () => {
  // The relay isn't there: the attempt closes and backs off.
  FakeWebSocket.made[0]!.close()
  await settle()
  const before = reads.length
  alarm()
  await settle()
  // A retry is scheduled, so the alarm leaves it alone; either way nothing re-reads a found file.
  expect(reads.length).toBe(before)
  bundled = OTHER
  relay.reconnect()
  await until(() => FakeWebSocket.made.length === 2)
  expect(reads.length).toBe(before + 1)
})

test("a pairing change re-reads the file", async () => {
  const before = reads.length
  bundled = undefined
  await stub.chrome.storage.local.set({ agentRelayPairingCode: CODE })
  await until(() => reads.length === before + 1)
  // No file now; the stored code takes over.
  await until(() => relay.state().pairing === "stored")
})

import { beforeEach, describe, expect, test } from "bun:test"
import { installChrome, settle } from "./chrome-stub"

const stub = installChrome()
const { AgentWindow } = await import("../src/background/agent-window")

/** The user's window, focused, at the given bounds. */
async function userWindow(bounds: { left: number; top: number; width: number; height: number }) {
  const window = await stub.chrome.windows.create({ ...bounds, focused: true })
  stub.state.created.length = 0
  return window
}

beforeEach(async () => {
  stub.state.windows.clear()
  stub.state.tabs.clear()
  stub.state.created.length = 0
  stub.state.activations.length = 0
  stub.state.focusedWindowId = undefined
  stub.state.displays = [{ left: 0, top: 0, width: 1512, height: 982 }]
  await stub.chrome.storage.session.remove("agentWindowId")
  await stub.chrome.storage.local.remove("agentTabsWindow")
})

describe("AgentWindow.open", () => {
  test("by default opens a background tab in the window the user last focused", async () => {
    const user = await userWindow({ left: 0, top: 30, width: 1512, height: 950 })
    const userTab = [...stub.state.tabs.values()].find((tab) => tab.windowId === user.id)!
    const tab = await AgentWindow.open("https://example.com/")
    expect(tab.windowId).toBe(user.id)
    expect(tab.active).toBe(false)
    expect(stub.state.created).toHaveLength(0)
    expect(stub.state.tabs.get(userTab.id)!.active).toBe(true)
    expect(stub.state.focusedWindowId).toBe(user.id)
    expect(stub.state.activations).toEqual([])
  })

  test("with only a popup window focused, opens in an unfocused new window, never a focused one", async () => {
    await stub.chrome.windows.create({ type: "popup", focused: true })
    stub.state.created.length = 0
    const tab = await AgentWindow.open("https://example.com/")
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false, type: "normal" })])
    expect(stub.state.windows.get(tab.windowId)?.focused).toBe(false)
  })

  test("with no window at all, makes one unfocused", async () => {
    const tab = await AgentWindow.open("https://example.com/")
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false, type: "normal" })])
    expect(stub.state.windows.get(tab.windowId)?.focused).toBe(false)
    expect(await AgentWindow.id()).toBeUndefined()
  })

  test("the separate setting opens tabs in the agent window", async () => {
    await stub.chrome.storage.local.set({ agentTabsWindow: "separate" })
    const user = await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const tab = await AgentWindow.open("https://example.com/")
    expect(tab.windowId).not.toBe(user.id)
    expect(tab.windowId).toBe((await AgentWindow.id())!)
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false })])
    expect(stub.state.focusedWindowId).toBe(user.id)
    expect(stub.state.activations).toEqual([])
  })

  test("an override from the relay wins over the setting, and switching affects new tabs only", async () => {
    const user = await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const separate = await AgentWindow.open("https://example.com/1", { override: "separate" })
    expect(separate.windowId).not.toBe(user.id)
    await stub.chrome.storage.local.set({ agentTabsWindow: "separate" })
    const current = await AgentWindow.open("https://example.com/2", { override: "current" })
    expect(current.windowId).toBe(user.id)
    await stub.chrome.storage.local.set({ agentTabsWindow: "current" })
    expect((await AgentWindow.open("https://example.com/3")).windowId).toBe(user.id)
    // The tab already in the agent window stays there.
    expect(stub.state.tabs.get(separate.id!)!.windowId).toBe(separate.windowId)
  })

  test("an unknown stored value means the default", async () => {
    await stub.chrome.storage.local.set({ agentTabsWindow: "elsewhere" })
    expect(await AgentWindow.placement()).toBe("current")
  })
})

describe("AgentWindow.openTab", () => {
  test("makes one unfocused window beside the user's, then opens background tabs in it", async () => {
    // A second display to the right of the laptop screen.
    stub.state.displays.push({ left: 1512, top: 0, width: 2560, height: 1440 })
    const user = await userWindow({ left: 0, top: 30, width: 1512, height: 950 })

    const first = await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toHaveLength(1)
    expect(stub.state.created[0]).toMatchObject({ focused: false, state: "normal", left: 1512, top: 30, width: 1280, height: 900 })
    expect(first.windowId).not.toBe(user.id)
    expect(stub.state.focusedWindowId).toBe(user.id)

    const second = await AgentWindow.openTab("https://example.org/")
    expect(stub.state.created).toHaveLength(1)
    expect(second.windowId).toBe(first.windowId)
    expect(second.active).toBe(false)
    expect(await AgentWindow.id()).toBe(first.windowId)
  })

  test("concurrent calls share one new window", async () => {
    await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const tabs = await Promise.all([1, 2, 3].map((n) => AgentWindow.openTab(`https://example.com/${n}`)))
    expect(stub.state.created).toHaveLength(1)
    expect(new Set(tabs.map((tab) => tab.windowId)).size).toBe(1)
  })

  test("makes the window again after the user closes it", async () => {
    await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    const first = await AgentWindow.openTab("https://example.com/")
    await stub.chrome.windows.remove(first.windowId)
    await settle()
    expect(await AgentWindow.id()).toBeUndefined()
    const again = await AgentWindow.openTab("https://example.com/")
    expect(again.windowId).not.toBe(first.windowId)
    expect(stub.state.created).toHaveLength(2)
  })

  test("a stored id of a window that's gone (another browser session) isn't reused", async () => {
    await stub.chrome.storage.session.set({ agentWindowId: 9999 })
    await userWindow({ left: 0, top: 30, width: 600, height: 600 })
    await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toHaveLength(1)
  })

  test("tries the left when there's no room on the right", async () => {
    stub.state.displays = [{ left: 0, top: 0, width: 2560, height: 1440 }]
    await userWindow({ left: 1500, top: 100, width: 1060, height: 1000 })
    await AgentWindow.openTab("https://example.com/")
    // Right: entirely off the screen, refused by Chrome; left fits.
    expect(stub.state.created.map(({ left, top }) => ({ left, top }))).toEqual([
      { left: 2560, top: 100 },
      { left: 220, top: 100 },
    ])
  })

  test("lets Chrome place it when no side has room (one screen the user's window fills)", async () => {
    await userWindow({ left: 0, top: 30, width: 1512, height: 950 })
    const tab = await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toHaveLength(5)
    expect(stub.state.created.at(-1)).toMatchObject({ focused: false, width: 1280, height: 900 })
    expect(stub.state.created.at(-1)?.left).toBeUndefined()
    expect(stub.state.windows.get(tab.windowId)?.focused).toBe(false)
  })

  test("without a focused window, opens with its size only", async () => {
    await AgentWindow.openTab("https://example.com/")
    expect(stub.state.created).toEqual([expect.objectContaining({ focused: false, width: 1280, height: 900 })])
    expect(stub.state.created[0]?.left).toBeUndefined()
  })
})

describe("AgentWindow.placements", () => {
  test("right, left, below, above the user's window", () => {
    expect(AgentWindow.placements({ left: 100, top: 50, width: 800, height: 600 }, { width: 400, height: 300 })).toEqual([
      { left: 900, top: 50, width: 400, height: 300 },
      { left: -300, top: 50, width: 400, height: 300 },
      { left: 100, top: 650, width: 400, height: 300 },
      { left: 100, top: -250, width: 400, height: 300 },
    ])
    expect(AgentWindow.placements({ left: 0 })).toEqual([])
  })
})

import { Data } from "effect"
import type { CdpEvent, JsonObject } from "./protocol.ts"
import type { ChildTarget, ConnectedTarget } from "./relay-types.ts"

type ClientCdpSessionAlias = Data.TaggedEnum<{
  Browser: {}
  Target: { readonly tabId: number; readonly targetId: string; readonly chromeSessionId?: string }
}>
export const ClientCdpSessionAlias = Data.taggedEnum<ClientCdpSessionAlias>()

type AnnouncedTarget = {
  readonly tabId: number
  readonly targetId: string
  readonly sessionId: string
  readonly parentSessionId?: string
}

type CdpClientState = {
  readonly aliases: Map<string, ClientCdpSessionAlias>
  readonly announcements: Map<string, AnnouncedTarget>
  readonly opencodeBrowserSessionId?: string
  readonly kind: "raw" | "sandbox"
  autoAttachParams?: JsonObject
}

export class CdpClientPool<Client extends object> implements Iterable<Client> {
  private readonly states = new Map<Client, CdpClientState>()
  private nextAliasId = 1
  private connectionGeneration = 0

  constructor(
    private readonly send: (client: Client, event: CdpEvent) => void,
    /** Observe every canonical session this client stops seeing, announced or silent. */
    private readonly retired: (client: Client, sessionId: string) => void,
  ) {}

  register(client: Client, opencodeBrowserSessionId?: string, kind: "raw" | "sandbox" = "raw"): void {
    if (this.states.has(client)) throw new Error("CDP client is already registered")
    this.states.set(client, {
      aliases: new Map(),
      announcements: new Map(),
      kind: opencodeBrowserSessionId ? kind : "raw",
      ...(opencodeBrowserSessionId ? { opencodeBrowserSessionId } : {}),
    })
    this.connectionGeneration += 1
  }

  unregister(client: Client): number | undefined {
    if (!this.states.delete(client) || this.states.size !== 0) return undefined
    return ++this.connectionGeneration
  }

  get size(): number {
    return this.states.size
  }

  has(client: Client): boolean {
    return this.states.has(client)
  }

  [Symbol.iterator](): IterableIterator<Client> {
    return this.states.keys()
  }

  sessionId(client: Client): string | undefined {
    return this.states.get(client)?.opencodeBrowserSessionId
  }

  isSandbox(client: Client): boolean {
    return this.states.get(client)?.kind === "sandbox"
  }

  hasSession(client: Client, sessionId: string): boolean {
    return this.states.get(client)?.announcements.has(sessionId) ?? false
  }

  announce(client: Client, target: ConnectedTarget | ChildTarget): void {
    const state = this.requireState(client)
    const targetId = target.targetInfo.targetId
    const existing = Array.from(state.announcements.values()).find((entry) => entry.targetId === targetId)
    if (existing?.sessionId === target.sessionId) return
    if (existing) this.detachSession(client, state, existing.sessionId)
    this.detachSession(client, state, target.sessionId)
    const parent = "parentSessionId" in target ? { parentSessionId: target.parentSessionId } : {}
    state.announcements.set(target.sessionId, { tabId: target.tabId, targetId, sessionId: target.sessionId, ...parent })
    this.send(client, {
      ...(parent.parentSessionId === undefined ? {} : { sessionId: parent.parentSessionId }),
      method: "Target.attachedToTarget",
      params: {
        sessionId: target.sessionId,
        targetInfo: { ...target.targetInfo, attached: true },
        waitingForDebugger: "waitingForDebugger" in target ? target.waitingForDebugger : false,
      },
    })
  }

  detach(client: Client, sessionId: string): void {
    const state = this.requireState(client)
    if (state.aliases.delete(sessionId)) return
    this.detachSession(client, state, sessionId, { notify: false })
  }

  detachTab(tabId: number, options: { readonly destroyed?: boolean } = {}): void {
    for (const [client, state] of this.states) {
      this.removeTargetAliases(state, (alias) => alias.tabId === tabId)
      for (const announced of state.announcements.values()) {
        if (announced.tabId === tabId) this.detachSession(client, state, announced.sessionId, options)
      }
    }
  }

  detachTarget(target: ChildTarget, options: { readonly notify?: boolean } = {}): void {
    for (const [client, state] of this.states) {
      this.removeTargetAliases(state, (alias) => alias.targetId === target.targetInfo.targetId)
      this.detachSession(client, state, target.sessionId, options)
    }
  }

  pruneInvisible(client: Client, canSeeTab: (tabId: number) => boolean): void {
    const state = this.requireState(client)
    this.removeTargetAliases(state, (alias) => !canSeeTab(alias.tabId))
    for (const announced of state.announcements.values()) {
      if (!canSeeTab(announced.tabId)) this.detachSession(client, state, announced.sessionId)
    }
  }

  sendToViewers(rootSessionId: string, event: CdpEvent, canSeeTab: (client: Client, tabId: number) => boolean): void {
    for (const [client, state] of this.states) {
      const announced = state.announcements.get(rootSessionId)
      if (!announced) continue
      if (!canSeeTab(client, announced.tabId)) {
        this.pruneInvisible(client, (tabId) => canSeeTab(client, tabId))
        continue
      }
      this.send(client, event)
    }
  }

  setAutoAttachParams(client: Client, params: JsonObject | undefined): void {
    const state = this.requireState(client)
    if (params === undefined) delete state.autoAttachParams
    else state.autoAttachParams = params
  }

  autoAttachParams(client: Client): JsonObject | undefined {
    return this.states.get(client)?.autoAttachParams
  }

  isCurrentIdleGeneration(generation: number): boolean {
    return this.states.size === 0 && this.connectionGeneration === generation
  }

  createBrowserAlias(client: Client): string {
    const aliasId = this.nextAlias("browser")
    this.requireState(client).aliases.set(aliasId, ClientCdpSessionAlias.Browser())
    return aliasId
  }

  createTargetAlias(client: Client, target: ConnectedTarget | ChildTarget): string {
    const aliasId = this.nextAlias("session")
    this.requireState(client).aliases.set(aliasId, ClientCdpSessionAlias.Target({
      tabId: target.tabId,
      targetId: target.targetInfo.targetId,
      ...("parentSessionId" in target ? { chromeSessionId: target.sessionId } : {}),
    }))
    return aliasId
  }

  alias(client: Client, aliasId: string): ClientCdpSessionAlias | undefined {
    return this.states.get(client)?.aliases.get(aliasId)
  }

  private detachSession(client: Client, state: CdpClientState, sessionId: string, options: {
    readonly notify?: boolean
    readonly destroyed?: boolean
  } = {}): void {
    const announced = state.announcements.get(sessionId)
    if (!announced) return
    state.announcements.delete(sessionId)
    this.removeTargetAliases(state, (alias) => alias.targetId === announced.targetId)
    // Descendants must disappear before their parent, including on replacement.
    for (const child of state.announcements.values()) {
      if (child.parentSessionId === sessionId) this.detachSession(client, state, child.sessionId, options)
    }
    this.retired(client, sessionId)
    if (options.notify === false) return
    if (options.destroyed && announced.parentSessionId === undefined) {
      this.send(client, { method: "Target.targetDestroyed", params: { targetId: announced.targetId } })
    }
    this.send(client, {
      ...(announced.parentSessionId === undefined ? {} : { sessionId: announced.parentSessionId }),
      method: "Target.detachedFromTarget",
      params: { sessionId, targetId: announced.targetId },
    })
  }

  private removeTargetAliases(state: CdpClientState, matches: (alias: Data.TaggedEnum.Value<ClientCdpSessionAlias, "Target">) => boolean): void {
    for (const [aliasId, alias] of state.aliases) {
      if (ClientCdpSessionAlias.$is("Target")(alias) && matches(alias)) state.aliases.delete(aliasId)
    }
  }

  private nextAlias(kind: "browser" | "session"): string {
    return `bc-client-${kind}-${this.nextAliasId++}`
  }

  private requireState(client: Client): CdpClientState {
    const state = this.states.get(client)
    if (!state) throw new Error("CDP client is not registered")
    return state
  }
}

import { Deferred, Effect, Fiber, Predicate } from "effect"
import type { CdpRoutedSession } from "./cdp-router.ts"
import type { CdpEvent, JsonObject } from "./protocol.ts"
import { getNumber, getObject, getString } from "./relay-helpers.ts"
import { boundedToken, runtimeFailureKind } from "./runtime-diagnostics.ts"
import type { TargetRegistry } from "./target-registry.ts"

const maxCachedContexts = 512

type Waiter = {
  readonly sessionId: string
  readonly ready: Deferred.Deferred<boolean>
  readonly nativeReady: (event: CdpEvent) => boolean
  /** Installed once the enable command succeeds. */
  replay?: () => boolean
}

type Contexts = Map<number, CdpEvent>
/** `contexts` is undefined once the cache overflowed and can no longer prove completeness. */
type ContextCache = { readonly current: () => boolean; contexts: Contexts | undefined }
type Requester = {
  readonly current: () => boolean
  readonly delivered: Map<number, string | undefined>
  frameId?: string
}

const routeSessionId = (route: CdpRoutedSession) => route.chromeSessionId ?? route.rootSessionId
const disableKey = (tabId: number, chromeSessionId?: string) => `${tabId}:${chromeSessionId ?? "root"}`
const contextAux = (event: CdpEvent) => getObject(getObject(event.params?.context)?.auxData)

export class CdpRuntime<Client extends object> {
  private readonly waiters = new Set<Waiter>()
  private readonly contexts = new Map<string, ContextCache>()
  private readonly requesters = new WeakMap<Client, Map<string, Requester>>()
  private readonly disabling = new Map<string, number>()

  constructor(private readonly options: {
    readonly registry: TargetRegistry
    readonly generation: () => number
    readonly send: (command: { readonly tabId: number; readonly sessionId?: string; readonly method: string; readonly params: JsonObject }) => Effect.Effect<JsonObject, Error>
    readonly sendEvent: (client: Client, event: CdpEvent) => void
    readonly trace?: (message: string) => void
  }) {}

  notify(event: CdpEvent): void {
    if (event.sessionId) this.recordContextEvent(event.sessionId, event)
    if (event.method !== "Runtime.executionContextCreated" || contextAux(event)?.isDefault !== true) return
    // Replay missing sibling contexts before waking the native waiter: resolving
    // its Deferred can synchronously retire the waiter's pending replay.
    for (const waiter of this.waiters) this.settle(waiter)
    for (const waiter of this.waiters) {
      if (waiter.sessionId === event.sessionId && waiter.nativeReady(event)) Deferred.doneUnsafe(waiter.ready, Effect.succeed(true))
    }
  }

  /** Observe the exact events actually sent to this canonical client. Aliases never enter here. */
  deliver(client: Client, event: CdpEvent): void {
    const requester = event.sessionId ? this.requesters.get(client)?.get(event.sessionId) : undefined
    const active = requester?.current() ? requester : undefined
    const context = getObject(event.params?.context)
    const id = getNumber(context, "id")
    const destroyedId = getNumber(event.params, "executionContextId")
    if (event.method === "Runtime.executionContextsCleared") active?.delivered.clear()
    if (event.method === "Runtime.executionContextDestroyed" && destroyedId !== undefined) {
      active?.delivered.delete(destroyedId)
    }
    if (event.method === "Runtime.executionContextCreated" && active?.frameId !== undefined && id !== undefined) {
      const unique = getString(context, "uniqueId")
      if (active.delivered.has(id) && active.delivered.get(id) === unique) return
      active.delivered.set(id, unique)
    }
    this.options.sendEvent(client, event)
  }

  /** Construct at request admission; invoke with the result only after its successful response is sent. */
  frameTreeResponse(client: Client, route: CdpRoutedSession, canContinue: () => boolean): (result: unknown) => void {
    const requester = this.requester(client, route, canContinue)
    return (result) => {
      const frameId = getString(getObject(getObject(getObject(result)?.frameTree)?.frame), "id")
      if (!Predicate.isString(frameId) || !requester.current()) return
      requester.frameId = frameId
      for (const waiter of this.waiters) this.settle(waiter)
    }
  }

  disconnect(client: Client): void {
    this.requesters.delete(client)
  }

  detach(client: Client, sessionId: string): void {
    this.requesters.get(client)?.delete(sessionId)
  }

  beginDisable(tabId: number, chromeSessionId?: string): () => void {
    const key = disableKey(tabId, chromeSessionId)
    this.disabling.set(key, (this.disabling.get(key) ?? 0) + 1)
    this.invalidate(tabId, chromeSessionId)
    return () => {
      const count = (this.disabling.get(key) ?? 1) - 1
      if (count === 0) this.disabling.delete(key)
      else this.disabling.set(key, count)
    }
  }

  private recordContextEvent(sessionId: string, event: CdpEvent): void {
    if (!event.method.startsWith("Runtime.executionContext") && event.method !== "Page.frameDetached") return
    const cache = this.cacheFor(sessionId)
    if (!cache) return
    switch (event.method) {
      case "Runtime.executionContextsCleared":
        cache.contexts = new Map()
        return
      case "Runtime.executionContextDestroyed": {
        const id = getNumber(event.params, "executionContextId")
        if (id !== undefined) cache.contexts?.delete(id)
        return
      }
      case "Page.frameDetached":
        for (const [id, created] of cache.contexts ?? []) {
          if (contextAux(created)?.frameId === event.params?.frameId) cache.contexts?.delete(id)
        }
        return
      case "Runtime.executionContextCreated": {
        const id = getNumber(getObject(event.params?.context), "id")
        if (!cache.contexts || id === undefined) return
        cache.contexts.set(id, event)
        if (cache.contexts.size > maxCachedContexts) cache.contexts = undefined
      }
    }
  }

  private invalidate(tabId: number, chromeSessionId?: string): void {
    for (const [sessionId] of this.contexts) {
      const target = this.options.registry.targets.get(sessionId) ?? this.options.registry.childTargets.get(sessionId)
      if (target?.tabId === tabId && (chromeSessionId === undefined || sessionId === chromeSessionId)) this.contexts.delete(sessionId)
    }
  }

  private cacheFor(sessionId: string): ContextCache | undefined {
    for (const [key, value] of this.contexts) if (!value.current()) this.contexts.delete(key)
    const root = this.options.registry.targets.get(sessionId)
    const child = this.options.registry.childTargets.get(sessionId)
    const parent = child ? this.options.registry.tabTargets.get(child.tabId) : undefined
    const route = root ? { tabId: root.tabId, rootSessionId: root.sessionId }
      : child && parent ? { tabId: child.tabId, rootSessionId: parent.sessionId, chromeSessionId: child.sessionId } : undefined
    if (!route) return undefined
    if (this.disabling.has(disableKey(route.tabId)) || this.disabling.has(disableKey(route.tabId, route.chromeSessionId))) return undefined
    let cache = this.contexts.get(sessionId)
    if (!cache) {
      cache = { current: this.capture(route), contexts: new Map() }
      this.contexts.set(sessionId, cache)
    }
    return cache
  }

  private requester(client: Client, route: CdpRoutedSession, canContinue: () => boolean): Requester {
    const sessions = this.requesters.get(client) ?? new Map<string, Requester>()
    this.requesters.set(client, sessions)
    const sessionId = routeSessionId(route)
    const existing = sessions.get(sessionId)
    if (existing?.current()) return existing
    const captured = this.capture(route)
    const next: Requester = {
      current: () => captured() && canContinue() && this.requesters.get(client) === sessions && sessions.get(sessionId) === next,
      delivered: new Map(),
    }
    sessions.set(sessionId, next)
    return next
  }

  readonly enable = Effect.fn("CdpRuntime.enable")(function* (
    this: CdpRuntime<Client>,
    route: CdpRoutedSession,
    params: JsonObject,
    canContinue: () => boolean,
    client?: Client,
  ) {
    const current = this.capture(route)
    const permitted = () => current() && canContinue()
    // Raw CDP clients need not request a frame tree. Preserve their ordinary
    // native-event path; cached replay requires a frame-tree request already admitted.
    const requester = client ? this.requesters.get(client)?.get(routeSessionId(route)) : undefined
    const rootFrame = () => requester && permitted() && requester.current() ? requester.frameId : undefined
    const first = yield* this.observe(route, Effect.suspend(() => permitted()
      ? this.options.send({
        tabId: route.tabId, method: "Runtime.enable", params,
        ...(route.chromeSessionId === undefined ? {} : { sessionId: route.chromeSessionId }),
      })
      : Effect.fail(new Error("CDP target changed before Runtime.enable"))), client && requester ? {
      replay: () => {
        const frameId = rootFrame()
        return frameId !== undefined && this.replayCached(client, route, frameId)
      },
      nativeReady: (event) => {
        const frameId = rootFrame()
        return frameId !== undefined && contextAux(event)?.frameId === frameId
      },
    } : {})
    this.trace(route, `runtime-enable defaultContextSeen=${first.seen}`)
    if (!first.seen && permitted()) {
      // The shared debugger may acknowledge enable without replaying its context.
      // Never run the recovery cycle against a successor generation or new owner.
      const retry = yield* this.observe(route, this.reset(route, "Runtime.disable", {}, permitted).pipe(
        Effect.andThen(() => this.reset(route, "Runtime.enable", params, permitted)),
      ))
      this.trace(route, `runtime-reset phase=missing-default-context defaultContextSeen=${retry.seen}`)
    }
    return first.result
  })

  readonly disableIdle = Effect.fn("CdpRuntime.disableIdle")(function* (this: CdpRuntime<Client>, stillIdle: () => boolean) {
    const { registry } = this.options
    const routes: CdpRoutedSession[] = registry.listRootTargets().map((target) => ({ tabId: target.tabId, rootSessionId: target.sessionId }))
    for (const target of registry.childTargets.values()) {
      const root = registry.tabTargets.get(target.tabId)
      if (root) routes.push({ tabId: target.tabId, rootSessionId: root.sessionId, chromeSessionId: target.sessionId })
    }
    const targets = routes.map((route) => ({ route, current: this.capture(route) }))
    for (const { route, current } of targets) {
      if (!stillIdle()) break
      yield* this.reset(route, "Runtime.disable", {}, () => stillIdle() && current())
    }
  })

  /** Replay a complete cache only when it already holds the requester's root-frame default context. */
  private replayCached(client: Client, route: CdpRoutedSession, frameId: string): boolean {
    const cache = this.contexts.get(routeSessionId(route))
    const contexts = cache?.current() ? cache.contexts : undefined
    if (!contexts || ![...contexts.values()].some((event) => {
      const aux = contextAux(event)
      return aux?.isDefault === true && aux.frameId === frameId
    })) return false
    for (const event of contexts.values()) this.deliver(client, event)
    this.trace(route, "runtime-replay defaultContextSeen=true")
    return true
  }

  private settle(waiter: Waiter): void {
    if (waiter.replay?.()) Deferred.doneUnsafe(waiter.ready, Effect.succeed(true))
  }

  private observe<A>(route: CdpRoutedSession, command: Effect.Effect<A, Error>, options: {
    readonly replay?: () => boolean
    readonly nativeReady?: (event: CdpEvent) => boolean
  } = {}): Effect.Effect<{ readonly result: A; readonly seen: boolean }, Error> {
    const runtime = this
    return Effect.acquireUseRelease(
      Effect.sync(() => {
        const waiter: Waiter = { sessionId: routeSessionId(route), ready: Deferred.makeUnsafe(), nativeReady: options.nativeReady ?? (() => true) }
        runtime.waiters.add(waiter)
        return waiter
      }),
      (waiter) => Effect.gen(function* () {
        // Start the window before sending: context events may precede the reply.
        const seen = yield* Effect.forkScoped(Deferred.await(waiter.ready).pipe(Effect.timeoutOrElse({
          duration: "3 seconds",
          orElse: () => Effect.succeed(false),
        })), { startImmediately: true })
        const result = yield* command
        if (options.replay) waiter.replay = options.replay
        runtime.settle(waiter)
        return { result, seen: yield* Fiber.join(seen) }
      }).pipe(Effect.scoped),
      (waiter) => Effect.sync(() => { runtime.waiters.delete(waiter) }),
    )
  }

  private reset(route: CdpRoutedSession, method: "Runtime.enable" | "Runtime.disable", params: JsonObject, current: () => boolean): Effect.Effect<void> {
    return Effect.suspend(() => {
      if (!current()) return Effect.void
      this.trace(route, `runtime-reset command=${method}`)
      return this.options.send({ tabId: route.tabId, method, params, ...(route.chromeSessionId === undefined ? {} : { sessionId: route.chromeSessionId }) }).pipe(
        Effect.match({
          onFailure: (error) => this.trace(route, `runtime-reset command=${method} outcome=failed failure=${runtimeFailureKind(error)}`),
          onSuccess: () => this.trace(route, `runtime-reset command=${method} outcome=ok`),
        }),
      )
    })
  }

  private capture(route: CdpRoutedSession): () => boolean {
    const { registry } = this.options
    const generation = this.options.generation()
    const root = registry.targets.get(route.rootSessionId)
    const owner = root?.opencodeBrowserSessionId
    const child = route.chromeSessionId === undefined ? undefined : registry.childTargets.get(route.chromeSessionId)
    return () => {
      const currentRoot = registry.routingRootTarget(route.tabId)
      if (!root || generation !== this.options.generation() || currentRoot?.sessionId !== root.sessionId || currentRoot.targetInfo.targetId !== root.targetInfo.targetId || currentRoot.opencodeBrowserSessionId !== owner) return false
      if (route.chromeSessionId === undefined) return true
      const currentChild = registry.childTargets.get(route.chromeSessionId)
      return child !== undefined && currentChild?.tabId === route.tabId && currentChild.targetInfo.targetId === child.targetInfo.targetId && currentChild.parentSessionId === child.parentSessionId
    }
  }

  private trace(route: CdpRoutedSession, message: string): void {
    this.options.trace?.(`${message} tab=${route.tabId} rootSession=${boundedToken(route.rootSessionId)} chromeSession=${boundedToken(route.chromeSessionId)}`)
  }
}

