// Gets the Chrome Web Store API refresh token the release workflow uses, once, on your own computer:
//   bun scripts/cws-auth.ts                 prints the refresh token once
//   bun scripts/cws-auth.ts --set-secret    stores it straight into GitHub (gh secret set CWS_REFRESH_TOKEN
//                                           --env chrome-web-store), so it never shows on screen
// It asks for the OAuth client's ID and secret (or reads CWS_CLIENT_ID / CWS_CLIENT_SECRET), opens Google's consent page
// in your browser with PKCE, receives the code on a one-time 127.0.0.1 redirect, and exchanges it. Nothing is written to
// disk. Sign in as the Google account that owns (or is a member of) the Chrome Web Store publisher.
// The OAuth client must be a "Desktop app" client, which allows loopback redirects (RELEASING.md).
import { spawn, spawnSync } from "node:child_process"
import { createHash, randomBytes } from "node:crypto"
import http from "node:http"
import type { AddressInfo } from "node:net"
import { createInterface } from "node:readline"
import { parseArgs } from "node:util"

const SCOPE = "https://www.googleapis.com/auth/chromewebstore"
const REPO = "anomalyco/browse"

function loopbackOverride(name: string, fallback: string) {
  const value = process.env[name]
  if (!value) return fallback
  const url = new URL(value)
  if (url.protocol !== "http:" || !["127.0.0.1", "localhost"].includes(url.hostname)) throw new Error(`${name} may only point at a loopback http server`)
  return value
}
const AUTH_URL = loopbackOverride("CWS_AUTH_URL", "https://accounts.google.com/o/oauth2/v2/auth")
const TOKEN_URL = loopbackOverride("CWS_TOKEN_URL", "https://oauth2.googleapis.com/token")

const base64url = (bytes: Buffer) => bytes.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "")

/** Reads a line from the terminal; a secret is read without echoing it. */
function ask(question: string, secret = false): Promise<string> {
  return new Promise((resolve) => {
    const output = process.stderr
    const prompt = createInterface({ input: process.stdin, output, terminal: true })
    if (secret) {
      const write = output.write.bind(output)
      ;(prompt as unknown as { _writeToOutput: (text: string) => void })._writeToOutput = (text: string) => {
        if (text.includes(question)) write(text)
      }
    }
    prompt.question(question, (answer) => {
      prompt.close()
      if (secret) output.write("\n")
      resolve(answer.trim())
    })
  })
}

function openBrowser(url: string) {
  const [command, args] = process.platform === "darwin" ? ["open", [url]] : process.platform === "win32" ? ["rundll32", ["url.dll,FileProtocolHandler", url]] : ["xdg-open", [url]]
  const child = spawn(command as string, args as string[], { stdio: "ignore", detached: true })
  child.on("error", () => {})
  child.unref()
}

async function main() {
  const { values } = parseArgs({ options: { "set-secret": { type: "boolean" }, "no-open": { type: "boolean" }, repo: { type: "string" } } })
  const clientId = process.env.CWS_CLIENT_ID?.trim() || (await ask("OAuth client ID: "))
  const clientSecret = [REDACTED] || (await ask("OAuth client secret (hidden): ", true))
  if (!clientId || !clientSecret) throw new Error("Both the client ID and secret are needed.")

  const verifier = base64url(randomBytes(32))
  const challenge = base64url(createHash("sha256").update(verifier).digest())
  const state = base64url(randomBytes(16))

  const server = http.createServer()
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve))
  const redirect = `http://127.0.0.1:${(server.address() as AddressInfo).port}/`
  const code = new Promise<string>((resolve, reject) => {
    server.on("request", (request, response) => {
      const url = new URL(request.url ?? "/", redirect)
      if (url.pathname !== "/") return void response.writeHead(404).end()
      const done = (status: number, message: string) => response.writeHead(status, { "content-type": "text/plain; charset=utf-8" }).end(message)
      if (url.searchParams.get("state") !== state) return done(400, "State mismatch; start again.")
      const error = url.searchParams.get("error")
      if (error) {
        done(400, `Google returned ${error}. You can close this tab.`)
        return reject(new Error(`Authorization failed: ${error}`))
      }
      const value = url.searchParams.get("code")
      if (!value) return done(400, "No code in the redirect.")
      done(200, "Authorized. You can close this tab and go back to the terminal.")
      resolve(value)
    })
  })

  const consent = `${AUTH_URL}?${new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirect,
    response_type: "code",
    scope: SCOPE,
    access_type: "offline",
    prompt: "consent",
    code_challenge: challenge,
    code_challenge_method: "S256",
    state,
  })}`
  console.error("Open this page and allow access (opening it in your browser):")
  console.error(`  ${consent}`)
  if (!values["no-open"]) openBrowser(consent)

  const timeout = setTimeout(() => {
    console.error("✗ Timed out after 5 minutes waiting for the redirect.")
    process.exit(1)
  }, 5 * 60_000)
  const authorization = await code.finally(() => {
    clearTimeout(timeout)
    server.close()
  })

  const response = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: clientId,
      client_secret: [REDACTED],
      code: authorization,
      code_verifier: verifier,
      grant_type: "authorization_code",
      redirect_uri: redirect,
    }),
  })
  const body = (await response.json().catch(() => ({}))) as { refresh_token?: string; scope?: string; error?: string; error_description?: string }
  if (!response.ok || !body.refresh_token)
    throw new Error(`Token exchange failed: ${response.status} ${body.error ?? ""} ${body.error_description ?? ""}${response.ok ? " (no refresh token; revoke the app's access at https://myaccount.google.com/permissions and run this again)" : ""}`)
  if (body.scope && !body.scope.split(" ").includes(SCOPE)) throw new Error(`The token doesn't carry the ${SCOPE} scope.`)

  if (values["set-secret"]) {
    const repo = values.repo ?? REPO
    const result = spawnSync("gh", ["secret", "set", "CWS_REFRESH_TOKEN", "--env", "chrome-web-store", "--repo", repo], {
      input: body.refresh_token,
      stdio: ["pipe", "inherit", "inherit"],
    })
    if (result.status !== 0) throw new Error("gh secret set failed (is gh installed and signed in with admin access to the repo?). Run without --set-secret to print the token instead.")
    console.error(`✓ Stored CWS_REFRESH_TOKEN in the chrome-web-store environment of ${repo}.`)
  } else {
    console.error("Refresh token (shown once; store it as the CWS_REFRESH_TOKEN secret of the chrome-web-store environment, then clear your terminal):")
    process.stdout.write(`${body.refresh_token}\n`)
  }
}

main().catch((error) => {
  console.error(`✗ ${(error as Error).message}`)
  process.exit(1)
})

import { dataRoot } from "./paths.ts"
import { Effect, Schema, Semaphore } from "effect"
import { spawn } from "node:child_process"
import fs from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { terminateChildProcess } from "./child-process.ts"
import { isNodeError, writeJsonFileAtomically } from "./fs-durability.ts"
import { redactKnownValues, type CredentialSlot } from "./network-redaction.ts"

const StoredCredentialSlot = Schema.Struct({
  ref: Schema.String.check(Schema.isPattern(/^BC_SECRET_[1-9][0-9]*$/)),
  value: Schema.String,
  sources: Schema.Array(Schema.String),
  expiresAt: Schema.optionalKey(Schema.String),
})

const StoredAuthProfile = Schema.Struct({
  version: Schema.Literal(1),
  name: Schema.String,
  createdAt: Schema.String,
  updatedAt: Schema.String,
  slots: Schema.Array(StoredCredentialSlot),
}).check(Schema.makeFilter((profile) => {
  const refs = profile.slots.map((slot) => slot.ref)
  if (new Set(refs).size !== refs.length) return "Auth profile refs must be unique"
  const sources = profile.slots.flatMap((slot) => slot.sources)
  return new Set(sources).size === sources.length ? undefined : "Auth profile sources must be unique"
}))

interface AuthProfile extends Schema.Schema.Type<typeof StoredAuthProfile> {}

export type AuthProfileSummary = {
  readonly name: string
  readonly createdAt: string
  readonly updatedAt: string
  readonly slotCount: number
  readonly slots: readonly {
    readonly ref: string
    readonly sources: readonly string[]
    readonly expiresAt?: string
    readonly expired: boolean
  }[]
}

export type AuthRunResult = {
  readonly exitCode: number
  readonly signal: NodeJS.Signals | null
  readonly stdout: string
  readonly stderr: string
  readonly stdoutTruncated: boolean
  readonly stderrTruncated: boolean
  readonly durationMs: number
}

export interface AuthProfileOptions {
  readonly baseDir?: string
}

export interface AuthRunOptions extends AuthProfileOptions {
  readonly name: string
  readonly command: string
  readonly args?: readonly string[]
  readonly cwd?: string
  readonly timeoutMs?: number
  readonly maxOutputBytes?: number
}

export class AuthProfileError extends Schema.TaggedError<AuthProfileError>()(
  "AuthProfile.Error",
  {
    message: Schema.String,
    operation: Schema.String,
    reason: Schema.Literals(["invalid-name", "not-found", "read-failed", "invalid-json", "invalid-profile", "write-failed", "run-failed"]),
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

const defaultBaseDir = (): string => path.join(dataRoot(), "secrets")
const writeLock = Semaphore.makeUnsafe(1)
const profileLockTimeoutMs = 30_000
const staleProfileLockMs = 60_000
const maximumRunOutputBytes = 10_000_000
const maximumTimeoutMs = 2_147_483_647

export const read = Effect.fn("AuthProfile.read")(function* (name: string, options: { readonly baseDir?: string } = {}) {
  const filePath = yield* profilePath(options.baseDir ?? defaultBaseDir(), name)
  const text = yield* Effect.tryPromise({
    try: () => fs.readFile(filePath, "utf8"),
    catch: (cause) => isNodeError(cause) && cause.code === "ENOENT"
      ? new AuthProfileError({ message: `Auth profile not found: ${name}`, operation: "read", reason: "not-found", cause })
      : new AuthProfileError({ message: `Could not read auth profile: ${name}`, operation: "read", reason: "read-failed", cause }),
  })
  return yield* Schema.decodeUnknownEffect(StoredAuthProfile)(yield* Effect.try({
    try: () => JSON.parse(text),
    catch: (cause) => new AuthProfileError({ message: `Auth profile is not valid JSON: ${name}`, operation: "read", reason: "invalid-json", cause }),
  })).pipe(
    Effect.mapError((cause) => cause instanceof AuthProfileError
      ? cause
      : new AuthProfileError({ message: `Auth profile has an invalid shape: ${name}`, operation: "read", reason: "invalid-profile", cause })),
  )
})

export const readOptional = Effect.fn("AuthProfile.readOptional")(function* (name: string, options: { readonly baseDir?: string } = {}) {
  return yield* read(name, options).pipe(
    Effect.catchIf((error) => error.reason === "not-found", () => Effect.succeed(undefined)),
  )
})

export function withLock<A, E, R>(
  name: string,
  options: { readonly baseDir?: string },
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E | AuthProfileError, R> {
  const baseDir = options.baseDir ?? defaultBaseDir()
  const acquire = Effect.gen(function* () {
    const filePath = yield* profilePath(baseDir, name)
    const lockPath = `${filePath}.lock`
    yield* Effect.tryPromise({
      try: async () => {
        await fs.mkdir(baseDir, { recursive: true, mode: 0o700 })
        await fs.chmod(baseDir, 0o700)
        const deadline = Date.now() + profileLockTimeoutMs
        while (true) {
          try {
            const handle = await fs.open(lockPath, "wx", 0o600)
            let written = false
            try {
              await handle.writeFile(`${process.pid}\n`)
              written = true
            } finally {
              await handle.close()
              if (!written) await fs.unlink(lockPath).catch(() => {})
            }
            return
          } catch (cause) {
            if (!isNodeError(cause) || cause.code !== "EEXIST") throw cause
            const stat = await fs.stat(lockPath).catch(() => undefined)
            if (stat && Date.now() - stat.mtimeMs > staleProfileLockMs) {
              await fs.unlink(lockPath).catch(() => {})
              continue
            }
            if (Date.now() >= deadline) throw new Error(`Timed out waiting for auth profile lock: ${name}`)
            await new Promise((resolve) => setTimeout(resolve, 25))
          }
        }
      },
      catch: (cause) => new AuthProfileError({ message: `Could not lock auth profile: ${name}`, operation: "lock", reason: "write-failed", cause }),
    })
    return lockPath
  })
  return Effect.acquireUseRelease(
    acquire,
    () => effect,
    (lockPath) => Effect.tryPromise({
      try: () => fs.unlink(lockPath).catch(() => {}).then(() => {}),
      catch: (cause) => new AuthProfileError({ message: `Could not release auth profile lock: ${name}`, operation: "lock", reason: "write-failed", cause }),
    }),
  )
}

const writeProfile = Effect.fnUntraced(function* (options: {
  readonly name: string
  readonly slots: readonly CredentialSlot[]
  readonly baseDir?: string
}) {
  const baseDir = options.baseDir ?? defaultBaseDir()
  const filePath = yield* profilePath(baseDir, options.name)
  const existing = yield* readOptional(options.name, { baseDir })
  const now = new Date().toISOString()
  const profile: AuthProfile = {
    version: 1,
    name: options.name,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    slots: options.slots.map((slot) => ({
      ref: slot.ref,
      value: slot.value,
      sources: [...slot.sources],
      ...(slot.expiresAt ? { expiresAt: slot.expiresAt } : {}),
    })),
  }
  yield* Schema.decodeUnknownEffect(StoredAuthProfile)(profile).pipe(
    Effect.mapError((cause) => new AuthProfileError({ message: `Auth profile has an invalid shape: ${options.name}`, operation: "write", reason: "invalid-profile", cause })),
  )
  if (existing && sameSlots(existing.slots, profile.slots)) return summary(existing)
  yield* Effect.tryPromise({
    try: () => writeJsonFileAtomically(filePath, profile, { dirMode: 0o700 }),
    catch: (cause) => new AuthProfileError({ message: `Could not write auth profile: ${options.name}`, operation: "write", reason: "write-failed", cause }),
  })
  return summary(profile)
})

export const write = Effect.fn("AuthProfile.write")(function* (options: {
  readonly name: string
  readonly slots: readonly CredentialSlot[]
  readonly baseDir?: string
}) {
  return yield* writeLock.withPermit(writeProfile(options))
})

export const status = Effect.fn("AuthProfile.status")(function* (name: string, options: AuthProfileOptions = {}) {
  return summary(yield* read(name, options))
})

export const run = Effect.fn("AuthProfile.run")(function* (options: AuthRunOptions) {
  if (!options.command.trim()) {
    return yield* new AuthProfileError({ message: "Auth command must not be empty", operation: "run", reason: "run-failed" })
  }
  const timeoutMs = options.timeoutMs ?? 120_000
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs <= 0 || timeoutMs > maximumTimeoutMs) {
    return yield* new AuthProfileError({ message: `Auth command timeout must be an integer between 1 and ${maximumTimeoutMs} milliseconds`, operation: "run", reason: "run-failed" })
  }
  const maxOutputBytes = options.maxOutputBytes ?? 1_000_000
  if (!Number.isSafeInteger(maxOutputBytes) || maxOutputBytes < 0 || maxOutputBytes > maximumRunOutputBytes) {
    return yield* new AuthProfileError({ message: `Auth command output limit must be an integer between 0 and ${maximumRunOutputBytes} bytes`, operation: "run", reason: "run-failed" })
  }
  const profile = yield* read(options.name, { ...(options.baseDir ? { baseDir: options.baseDir } : {}) })
  const startedAt = Date.now()
  const maxSecretBytes = profile.slots.reduce((max, slot) => Math.max(max, Buffer.byteLength(slot.value)), 0)
  const result = yield* runChild({
      command: options.command,
      args: options.args ?? [],
      ...(options.cwd ? { cwd: options.cwd } : {}),
      timeoutMs,
      maxOutputBytes: maxOutputBytes + maxSecretBytes,
      env: Object.fromEntries(profile.slots.map((slot) => [slot.ref, slot.value])),
    }).pipe(
      Effect.mapError((cause) => new AuthProfileError({ message: `Could not run command with auth profile ${options.name}`, operation: "run", reason: "run-failed", cause })),
    )
  const stdout = redactOutput(result.stdout, profile.slots, maxOutputBytes)
  const stderr = redactOutput(result.stderr, profile.slots, maxOutputBytes)
  return {
    ...result,
    stdout: stdout.text,
    stderr: stderr.text,
    stdoutTruncated: result.stdoutTruncated || stdout.truncated,
    stderrTruncated: result.stderrTruncated || stderr.truncated,
    durationMs: Date.now() - startedAt,
  } satisfies AuthRunResult
})

function summary(profile: AuthProfile): AuthProfileSummary {
  const now = Date.now()
  return {
    name: profile.name,
    createdAt: profile.createdAt,
    updatedAt: profile.updatedAt,
    slotCount: profile.slots.length,
    slots: profile.slots.map((slot) => ({
      ref: slot.ref,
      sources: [...slot.sources],
      ...(slot.expiresAt ? { expiresAt: slot.expiresAt } : {}),
      expired: slot.expiresAt ? Date.parse(slot.expiresAt) <= now : false,
    })),
  }
}

function profilePath(baseDir: string, name: string): Effect.Effect<string, AuthProfileError> {
  return /^[a-z0-9][a-z0-9._-]{0,63}$/i.test(name)
    ? Effect.succeed(path.join(baseDir, `${name}.json`))
    : Effect.fail(new AuthProfileError({ message: `Invalid auth profile name: ${name}`, operation: "path", reason: "invalid-name" }))
}

function sameSlots(left: readonly CredentialSlot[], right: readonly CredentialSlot[]): boolean {
  return JSON.stringify(left) === JSON.stringify(right)
}

function redactOutput(text: string, slots: readonly CredentialSlot[], maxBytes: number): { readonly text: string; readonly truncated: boolean } {
  const bytes = Buffer.from(text)
  let cutoff = Math.min(bytes.length, maxBytes)
  let changed = true
  while (changed) {
    changed = false
    for (const slot of slots) {
      if (!slot.value) continue
      const secret = [REDACTED]
      let start = bytes.indexOf(secret)
      while (start >= 0 && start < cutoff) {
        if (start + secret.length > cutoff) {
          cutoff = start
          changed = true
          break
        }
        start = bytes.indexOf(secret, start + secret.length)
      }
    }
  }
  return {
    text: redactKnownValues(bytes.subarray(0, cutoff).toString("utf8"), slots),
    truncated: cutoff < bytes.length,
  }
}

function runChild(options: {
  readonly command: string
  readonly args: readonly string[]
  readonly cwd?: string
  readonly timeoutMs: number
  readonly maxOutputBytes: number
  readonly env: Readonly<Record<string, string>>
}): Effect.Effect<Omit<AuthRunResult, "durationMs">, Error> {
  return Effect.callback((resume) => {
    const child = spawn(options.command, [...options.args], {
      ...(options.cwd ? { cwd: options.cwd } : {}),
      env: childEnvironment(options.env),
      detached: process.platform !== "win32",
      stdio: ["ignore", "pipe", "pipe"],
    })
    const stdout: Buffer[] = []
    const stderr: Buffer[] = []
    let stdoutBytes = 0
    let stderrBytes = 0
    let stdoutTruncated = false
    let stderrTruncated = false
    const append = (chunks: Buffer[], chunk: Buffer, currentBytes: number): number => {
      const remaining = options.maxOutputBytes - currentBytes
      if (remaining <= 0) return currentBytes
      chunks.push(chunk.subarray(0, remaining))
      return currentBytes + Math.min(chunk.length, remaining)
    }
    child.stdout.on("data", (chunk: Buffer) => {
      const next = append(stdout, chunk, stdoutBytes)
      stdoutTruncated ||= next - stdoutBytes < chunk.length
      stdoutBytes = next
    })
    child.stderr.on("data", (chunk: Buffer) => {
      const next = append(stderr, chunk, stderrBytes)
      stderrTruncated ||= next - stderrBytes < chunk.length
      stderrBytes = next
    })
    let closed = false
    let settled = false
    let closePromiseResolve: (() => void) | undefined
    const closePromise = new Promise<void>((resolve) => {
      closePromiseResolve = resolve
    })
    const timeout = setTimeout(() => {
      void terminateChildProcess({ child, exit: closePromise, graceMs: 1_000, isExited: () => closed })
    }, options.timeoutMs)
    child.once("error", (cause) => {
      clearTimeout(timeout)
      closed = true
      closePromiseResolve?.()
      if (settled) return
      settled = true
      resume(Effect.fail(cause))
    })
    child.once("close", (code, signal) => {
      clearTimeout(timeout)
      closed = true
      closePromiseResolve?.()
      if (settled) return
      settled = true
      resume(Effect.succeed({
        exitCode: code ?? 1,
        signal,
        stdout: Buffer.concat(stdout).toString("utf8"),
        stderr: Buffer.concat(stderr).toString("utf8"),
        stdoutTruncated,
        stderrTruncated,
      }))
    })
    return Effect.promise(() => terminateChildProcess({ child, exit: closePromise, graceMs: 1_000, isExited: () => closed }))
  })
}

function childEnvironment(profile: Readonly<Record<string, string>>): NodeJS.ProcessEnv {
  const inherited = Object.fromEntries(
    Object.entries(process.env).filter(([name]) => !/^BC_SECRET_[1-9][0-9]*$/.test(name)),
  )
  return { ...inherited, ...profile }
}

import { Effect, Match, Schema } from "effect"
import type { Page } from "patchright-core"
import {
  AuthenticatedJsonOutcome,
  type AuthenticatedJsonMethod,
  type AuthenticatedJsonRequest,
} from "./relay-schema.ts"

const defaultTimeoutMs = 30_000
const defaultMaxResponseBytes = 2_000_000

export class AuthenticatedOriginError extends Schema.TaggedError<AuthenticatedOriginError>()(
  "AuthenticatedOrigin.Error",
  {
    message: Schema.String,
    reason: Schema.Literals(["invalid-request", "page-failed"]),
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

type RequestOptions = Omit<AuthenticatedJsonRequest, "sessionId">

type PageRequestInput = {
  readonly origin: string
  readonly method: AuthenticatedJsonMethod
  readonly url: string
  readonly headers?: Readonly<Record<string, string>>
  readonly body?: unknown
  readonly timeoutMs: number
  readonly maxResponseBytes: number
}

export const requestJson = Effect.fn("AuthenticatedOrigin.requestJson")(function* (
  page: Page,
  request: RequestOptions,
) {
  const target = yield* Effect.try({
    try: () => {
      const origin = normalizeOrigin(request.origin)
      return {
        origin,
        requestUrl: resolveRequestUrl(origin, request.path),
        startUrl: request.startUrl === undefined ? undefined : resolveStartUrl(origin, request.startUrl),
      }
    },
    catch: (cause) => cause instanceof AuthenticatedOriginError
      ? cause
      : new AuthenticatedOriginError({
          message: "Invalid authenticated origin request",
          reason: "invalid-request",
          cause,
        }),
  })
  const { origin, requestUrl, startUrl } = target

  if (pageOrigin(page.url()) !== origin && startUrl !== undefined) {
    yield* Effect.tryPromise({
      try: () => page.goto(startUrl, { waitUntil: "domcontentloaded", timeout: request.timeoutMs ?? defaultTimeoutMs }),
      catch: (cause) => new AuthenticatedOriginError({
        message: cause instanceof Error ? cause.message : "Navigate to authenticated origin",
        reason: "page-failed",
        cause,
      }),
    })
  }

  const actualOrigin = pageOrigin(page.url())
  if (actualOrigin !== origin) {
    return AuthenticatedJsonOutcome.cases.OriginMismatch.make({
      expectedOrigin: origin,
      actualOrigin,
    })
  }

  const input: PageRequestInput = {
    origin,
    method: request.method,
    url: requestUrl,
    ...(request.headers === undefined ? {} : { headers: request.headers }),
    ...(request.body === undefined ? {} : { body: request.body }),
    timeoutMs: request.timeoutMs ?? defaultTimeoutMs,
    maxResponseBytes: request.maxResponseBytes ?? defaultMaxResponseBytes,
  }

  const pageResult = yield* Effect.tryPromise({
    try: () => page.evaluate(runPageRequest, input),
    catch: (cause) => new AuthenticatedOriginError({
      message: cause instanceof Error ? cause.message : "Run authenticated page request",
      reason: "page-failed",
      cause,
    }),
  }).pipe(Effect.uninterruptible)

  return Match.value(pageResult).pipe(
    Match.when({ kind: "OriginMismatch" }, ({ expectedOrigin, actualOrigin }) =>
      AuthenticatedJsonOutcome.cases.OriginMismatch.make({ expectedOrigin, actualOrigin })),
    Match.when({ kind: "HttpError" }, ({ status }) =>
      AuthenticatedJsonOutcome.cases.HttpError.make({ status })),
    Match.when({ kind: "ResponseTooLarge" }, ({ status, maxResponseBytes }) =>
      AuthenticatedJsonOutcome.cases.ResponseTooLarge.make({ status, maxResponseBytes })),
    Match.when({ kind: "Success" }, ({ status, value }) =>
      AuthenticatedJsonOutcome.cases.Success.make({ status, value })),
    Match.when({ kind: "InvalidJson" }, ({ status }) =>
      AuthenticatedJsonOutcome.cases.InvalidJson.make({ status })),
    Match.when({ kind: "RequestFailed" }, ({ outcome }) =>
      AuthenticatedJsonOutcome.cases.RequestFailed.make({ outcome })),
    Match.exhaustive,
  )
})

export function normalizeOrigin(value: string): string {
  let url: URL
  try {
    url = new URL(value)
  } catch (cause) {
    throw new AuthenticatedOriginError({
      message: `Invalid authenticated origin: ${value}`,
      reason: "invalid-request",
      cause,
    })
  }
  if ((url.protocol !== "https:" && url.protocol !== "http:") || url.username || url.password) {
    throw new AuthenticatedOriginError({
      message: `Authenticated origin must be an HTTP(S) origin without credentials: ${value}`,
      reason: "invalid-request",
    })
  }
  if (url.pathname !== "/" || url.search || url.hash) {
    throw new AuthenticatedOriginError({
      message: `Authenticated origin must not include a path, query, or fragment: ${value}`,
      reason: "invalid-request",
    })
  }
  return url.origin
}

function resolveRequestUrl(origin: string, path: string): string {
  if (!path.startsWith("/") || path.startsWith("//")) {
    throw new AuthenticatedOriginError({
      message: "Authenticated request path must start with one slash",
      reason: "invalid-request",
    })
  }
  const url = new URL(path, origin)
  if (url.origin !== origin) {
    throw new AuthenticatedOriginError({
      message: `Authenticated request escaped its declared origin: ${path}`,
      reason: "invalid-request",
    })
  }
  return url.toString()
}

export function resolveStartUrl(origin: string, value: string): string {
  const url = new URL(value, origin)
  if (url.origin !== origin) {
    throw new AuthenticatedOriginError({
      message: `Authenticated origin startUrl must stay on ${origin}`,
      reason: "invalid-request",
    })
  }
  return url.toString()
}

function pageOrigin(value: string): string {
  try {
    return new URL(value).origin
  } catch {
    return "null"
  }
}

type PageRequestResult =
  | { readonly kind: "OriginMismatch"; readonly expectedOrigin: string; readonly actualOrigin: string }
  | { readonly kind: "HttpError"; readonly status: number }
  | { readonly kind: "ResponseTooLarge"; readonly status: number; readonly maxResponseBytes: number }
  | { readonly kind: "Success"; readonly status: number; readonly value: Schema.Schema.Type<typeof Schema.Json> }
  | { readonly kind: "InvalidJson"; readonly status: number }
  | { readonly kind: "RequestFailed"; readonly outcome: "not-sent" | "unknown" }

async function runPageRequest(input: PageRequestInput): Promise<PageRequestResult> {
  if (window.location.origin !== input.origin) {
    return {
      kind: "OriginMismatch",
      expectedOrigin: input.origin,
      actualOrigin: window.location.origin,
    }
  }

  const controller = new AbortController()
  const timeout = window.setTimeout(() => controller.abort(), input.timeoutMs)
  let requestStarted = false
  try {
    const body = input.body === undefined ? undefined : JSON.stringify(input.body)
    const headers: Record<string, string> = {
      ...(body === undefined ? {} : { "content-type": "application/json" }),
      ...(input.headers ?? {}),
    }
    requestStarted = true
    const response = await window.fetch(input.url, {
      method: input.method,
      credentials: "same-origin",
      mode: "same-origin",
      redirect: "error",
      signal: controller.signal,
      ...(Object.keys(headers).length > 0 ? { headers } : {}),
      ...(body === undefined ? {} : { body }),
    })

    if (!response.ok) {
      await response.body?.cancel().catch(() => undefined)
      return { kind: "HttpError", status: response.status }
    }

    const reader = response.body?.getReader()
    const decoder = new TextDecoder()
    let byteCount = 0
    let text = ""
    if (reader) {
      while (true) {
        const chunk = await reader.read()
        if (chunk.done) break
        byteCount += chunk.value.byteLength
        if (byteCount > input.maxResponseBytes) {
          await reader.cancel().catch(() => undefined)
          return {
            kind: "ResponseTooLarge",
            status: response.status,
            maxResponseBytes: input.maxResponseBytes,
          }
        }
        text += decoder.decode(chunk.value, { stream: true })
      }
      text += decoder.decode()
    }

    try {
      return {
        kind: "Success",
        status: response.status,
        value: text ? JSON.parse(text) : null,
      }
    } catch {
      return { kind: "InvalidJson", status: response.status }
    }
  } catch {
    return {
      kind: "RequestFailed",
      outcome: requestStarted ? "unknown" : "not-sent",
    }
  } finally {
    window.clearTimeout(timeout)
  }
}

/**
 * Relay-level CDP guardrails.
 *
 * The relay refuses a small set of CDP methods that would destroy the user's
 * real browser state (Browse drives the user's own browser, with
 * their real logins). Read-only sessions additionally refuse input-dispatching
 * methods so "go look at X" tasks cannot click or type.
 *
 * Cookies are scoped to the client's attached pages: cookie reads return only
 * cookies that apply to those pages' hosts, and cookie writes are refused for
 * any other host, so a prompt-injected script cannot dump or plant the
 * profile's cookies for every site. OPENCODE_BROWSER_ALLOW_ALL_COOKIES=1 on
 * the relay lifts the scope.
 *
 * Site storage is scoped the same way: IndexedDB, Cache Storage, DOM storage,
 * shared storage, interest groups and the other Storage/ServiceWorker methods
 * that name an origin or storage key are handled in the browser process for
 * any origin, so they are refused unless that origin is one of the session's
 * page hosts (OPENCODE_BROWSER_ALLOW_ALL_STORAGE=1 lifts it). Methods that
 * observe or read every origin's state at once are refused outright.
 *
 * Navigations to browser-internal and local documents (file:, chrome:,
 * chrome-extension:, devtools:, view-source:, ...) are refused for
 * Page.navigate and Target.createTarget; OPENCODE_BROWSER_ALLOW_FILE_URLS=1
 * allows file: only. (Page script can't reach them either: Chromium refuses
 * renderer-initiated navigations from web pages to those schemes.)
 *
 * Pure module: given a method and session context, return a rejection message
 * or null. The relay turns a rejection into a normal CDP error response for
 * that command id, so the calling script fails loudly without breaking the
 * connection.
 */

const alwaysBlocked = new Map<string, string>([
  ["Network.clearBrowserCookies", "it would log the user out of every site in their browser"],
  ["Network.clearBrowserCache", "it would clear the user's entire browser cache"],
  ["Storage.clearCookies", "it would log the user out of every site in their browser"],
  ["Network.deleteCookies", "it would delete the user's cookies and can log them out"],
  ["Storage.clearDataForOrigin", "it would erase a site's cookies and stored data in the user's browser"],
  ["Storage.clearDataForStorageKey", "it would erase a site's stored data in the user's browser"],
  ["Browser.close", "it would close the user's browser"],
])

const readOnlyBlockedPrefixes = ["Input."] as const

export type GuardContext = {
  readonly method: string
  readonly readOnly: boolean
  readonly sessionId?: string | undefined
  readonly params?: Record<string, unknown> | undefined
  /** URLs of the pages the client can see; cookie access is limited to their hosts. */
  readonly pageUrls?: () => readonly string[]
}

export const allowAllCookiesEnvironmentVariable = "OPENCODE_BROWSER_ALLOW_ALL_COOKIES"
const allowsAllCookies = (): boolean => process.env[allowAllCookiesEnvironmentVariable] === "1"
const allowsForeground = (): boolean => process.env.OPENCODE_BROWSER_ALLOW_FOREGROUND === "1"

const cookieReadMethods = new Set(["Storage.getCookies", "Network.getAllCookies", "Network.getCookies"])

export const allowAllStorageEnvironmentVariable = "OPENCODE_BROWSER_ALLOW_ALL_STORAGE"
const allowsAllStorage = (): boolean => process.env[allowAllStorageEnvironmentVariable] === "1"
export const allowFileUrlsEnvironmentVariable = "OPENCODE_BROWSER_ALLOW_FILE_URLS"
const allowsFileUrls = (): boolean => process.env[allowFileUrlsEnvironmentVariable] === "1"

/** Domains whose methods address site storage by origin or storage key. */
const storageDomains = ["IndexedDB.", "CacheStorage.", "DOMStorage.", "Storage.", "ServiceWorker."] as const
/** Storage methods that name no origin and touch only the attached page (or nothing site-specific). */
const storageMethodsWithoutOrigin = new Set([
  "IndexedDB.enable", "IndexedDB.disable",
  "CacheStorage.enable", "CacheStorage.disable",
  "DOMStorage.enable", "DOMStorage.disable",
  "ServiceWorker.enable", "ServiceWorker.disable", "ServiceWorker.setForceUpdateOnPageLoad",
  "Storage.getStorageKeyForFrame", "Storage.getStorageKey", "Storage.getRelatedWebsiteSets",
  "Storage.getAffectedUrlsForThirdPartyCookieMetadata",
])
/** Methods that read, observe or reset every origin's state at once. */
const storageMethodsForAllOrigins = new Map<string, string>([
  ["Storage.getTrustTokens", "it reads the private state tokens of every site"],
  ["Storage.setInterestGroupTracking", "it reports every site's interest groups"],
  ["Storage.setInterestGroupAuctionTracking", "it reports every site's ad auctions"],
  ["Storage.setSharedStorageTracking", "it reports every site's shared storage"],
  ["Storage.runBounceTrackingMitigations", "it deletes state of sites in the user's browser"],
  ["Storage.setProtectedAudienceKAnonymity", "it changes ad state of every site"],
  ["ServiceWorker.stopAllWorkers", "it stops every site's service workers"],
])
/** Parameter names that carry an origin, a storage key (serialized "https://host/^0..."), or a URL in one. */
const originParamNames = ["securityOrigin", "storageKey", "origin", "ownerOrigin", "issuerOrigin", "scopeURL", "topLevelSite"] as const

/** The host a serialized origin, storage key or URL belongs to; undefined when it can't be read. */
function storageHost(value: string): string | undefined {
  // A storage key's first part is its origin; partitioned keys append "^0<top-level site>" and similar.
  const origin = value.split("^")[0] ?? ""
  try {
    const parsed = new URL(origin)
    return parsed.hostname ? parsed.hostname.toLowerCase() : undefined
  } catch {
    return undefined
  }
}

/** Every origin-like value a storage command addresses. */
function storageOrigins(params: Record<string, unknown> | undefined): string[] {
  if (!params) return []
  const values: string[] = []
  const collect = (object: unknown) => {
    if (object === null || typeof object !== "object") return
    for (const name of originParamNames) {
      const value = (object as Record<string, unknown>)[name]
      if (typeof value === "string" && value) values.push(value)
    }
  }
  collect(params)
  // DOMStorage.* storageId, IndexedDB/CacheStorage storageBucket, Storage.deleteStorageBucket bucket.
  collect(params.storageId)
  collect(params.storageBucket)
  collect(params.bucket)
  // Cache ids are "<storage key>|<cache name>".
  if (typeof params.cacheId === "string") values.push(params.cacheId.split("|")[0] ?? "")
  return values
}

function guardStorageAccess(context: GuardContext): string | null {
  if (!storageDomains.some((domain) => context.method.startsWith(domain))) return null
  if (allowsAllStorage()) return null
  const everyOrigin = storageMethodsForAllOrigins.get(context.method)
  if (everyOrigin) {
    return `Browse blocked ${context.method}: ${everyOrigin}. Set ${allowAllStorageEnvironmentVariable}=1 on the relay to allow it.`
  }
  if (storageMethodsWithoutOrigin.has(context.method)) return null
  const hosts = pageHosts(context.pageUrls?.() ?? [])
  const origins = storageOrigins(context.params)
  const outside = origins.length === 0
    ? "a request that names no origin or storage key"
    : origins.find((origin) => {
        const host = storageHost(origin)
        return host === undefined || !hosts.includes(host)
      })
  if (outside === undefined) return null
  return `Browse blocked ${context.method}: site storage can only be used for the hosts of this session's attached pages (${hosts.length > 0 ? hosts.join(", ") : "none"}), not ${outside}. Set ${allowAllStorageEnvironmentVariable}=1 on the relay to allow it.`
}

/** Schemes agents can't open: browser-internal pages, other extensions, DevTools, and local files. */
const restrictedNavigationSchemes = new Set([
  "file:", "chrome:", "chrome-extension:", "chrome-untrusted:", "chrome-search:", "devtools:", "view-source:",
  "edge:", "brave:", "opera:", "vivaldi:", "filesystem:",
])

function guardNavigation(context: GuardContext): string | null {
  if (context.method !== "Page.navigate" && context.method !== "Target.createTarget") return null
  const url = context.params?.url
  if (typeof url !== "string") return null
  let scheme: string
  try {
    // WHATWG parsing strips the whitespace and control characters a browser would ignore too.
    scheme = new URL(url).protocol.toLowerCase()
  } catch {
    return null
  }
  if (!restrictedNavigationSchemes.has(scheme)) return null
  if (scheme === "file:" && allowsFileUrls()) return null
  const hint = scheme === "file:"
    ? ` Set ${allowFileUrlsEnvironmentVariable}=1 on the relay to allow file: URLs.`
    : ""
  return `Browse blocked ${context.method} to a ${scheme} URL: agents can't open browser-internal pages, other extensions, DevTools or local files.${hint}`
}

function pageHosts(urls: readonly string[]): string[] {
  const hosts: string[] = []
  for (const url of urls) {
    try {
      const parsed = new URL(url)
      if ((parsed.protocol === "http:" || parsed.protocol === "https:") && parsed.hostname) hosts.push(parsed.hostname.toLowerCase())
    } catch {
      // Ignore unparsable target URLs.
    }
  }
  return hosts
}

/** True when a cookie for `cookieDomain` is sent to `host` (domain cookies match subdomains). */
function cookieAppliesToHost(cookieDomain: string, host: string): boolean {
  const domain = cookieDomain.toLowerCase().replace(/^\./, "")
  return domain.length > 0 && (host === domain || host.endsWith(`.${domain}`))
}

function cookieDomainOf(cookie: unknown): string | undefined {
  if (cookie === null || typeof cookie !== "object") return undefined
  const { domain, url } = cookie as { readonly domain?: unknown; readonly url?: unknown }
  if (typeof url === "string") {
    try {
      return new URL(url).hostname
    } catch {
      return undefined
    }
  }
  return typeof domain === "string" ? domain : undefined
}

function guardCookieWrite(context: GuardContext): string | null {
  const cookies = context.method === "Network.setCookie"
    ? [context.params]
    : Array.isArray(context.params?.cookies) ? context.params.cookies as unknown[] : []
  const hosts = pageHosts(context.pageUrls?.() ?? [])
  for (const cookie of cookies) {
    const domain = cookieDomainOf(cookie)
    if (!domain || !hosts.some((host) => cookieAppliesToHost(domain, host))) {
      return `Browse blocked ${context.method}: cookies can only be set for the hosts of this session's attached pages (${hosts.length > 0 ? hosts.join(", ") : "none"}), not ${domain ?? "a cookie without a domain or url"}. Set ${allowAllCookiesEnvironmentVariable}=1 on the relay to allow it.`
    }
  }
  return null
}

/**
 * Returns a human-readable rejection message when the method must be blocked,
 * or null when the command may be forwarded to the browser.
 */
export function guardCdpMethod(context: GuardContext): string | null {
  const reason = alwaysBlocked.get(context.method)
  if (reason) {
    return `Browse blocked ${context.method}: ${reason}. This command is always blocked by the relay.`
  }
  if (context.method.startsWith("WebAuthn.")) {
    // A virtual authenticator would let a script register or answer passkey ceremonies as the user. Passkeys in agent
    // tabs come only from Deadbolt grants, through the relay (passkey-bridge.ts).
    return `Browse blocked ${context.method}: agents can't drive WebAuthn or add virtual authenticators. Passkey sign-ins in agent tabs use the logins the user granted in Deadbolt. This command is always blocked by the relay.`
  }
  if (context.method === "Page.bringToFront" && !allowsForeground()) {
    return "Browse blocked Page.bringToFront: it raises the user's browser window over their work. Use handoff() when the user needs to act in the tab, or set OPENCODE_BROWSER_ALLOW_FOREGROUND=1 on the relay to allow it."
  }
  if ((context.method === "Storage.setCookies" || context.method === "Network.setCookies" || context.method === "Network.setCookie") && !allowsAllCookies()) {
    const rejection = guardCookieWrite(context)
    if (rejection) return rejection
  }
  if (!cookieReadMethods.has(context.method) && context.method !== "Storage.setCookies") {
    const rejection = guardStorageAccess(context)
    if (rejection) return rejection
  }
  const navigation = guardNavigation(context)
  if (navigation) return navigation
  if (context.method === "Network.loadNetworkResource" && !allowsAllStorage()) {
    // DevTools' resource loader fetches from the browser process with the user's credentials and no same-origin policy.
    const url = context.params?.url
    const hosts = pageHosts(context.pageUrls?.() ?? [])
    const host = typeof url === "string" ? pageHosts([url])[0] : undefined
    if (host === undefined || !hosts.includes(host)) {
      return `Browse blocked Network.loadNetworkResource: it loads URLs with the user's credentials outside the page's same-origin policy, so only the hosts of this session's attached pages (${hosts.length > 0 ? hosts.join(", ") : "none"}) are allowed. Set ${allowAllStorageEnvironmentVariable}=1 on the relay to allow it.`
    }
  }
  if (context.readOnly && readOnlyBlockedPrefixes.some((prefix) => context.method.startsWith(prefix))) {
    const session = context.sessionId ? `Session ${context.sessionId}` : "This session"
    return `${session} is read-only: ${context.method} is blocked. Use a session created without --read-only to interact with pages.`
  }
  return null
}

/**
 * Narrow a forwarded command's result to what the client may see: cookie
 * reads keep only cookies that apply to the hosts of the client's pages.
 */
export function scopeCdpResult<Result>(options: {
  readonly method: string
  readonly result: Result
  readonly pageUrls: () => readonly string[]
}): Result {
  if (!cookieReadMethods.has(options.method) || allowsAllCookies()) return options.result
  const result = options.result
  if (result === null || typeof result !== "object" || !Array.isArray((result as { cookies?: unknown }).cookies)) return result
  const hosts = pageHosts(options.pageUrls())
  const cookies = ((result as unknown as { cookies: unknown[] }).cookies).filter((cookie) => {
    const domain = cookieDomainOf(cookie)
    return domain !== undefined && hosts.some((host) => cookieAppliesToHost(domain, host))
  })
  return { ...result, cookies } as Result
}

import { ClientCdpSessionAlias, type CdpClientPool } from "./cdp-client-pool.ts"
import { canClientSeeTarget } from "./cdp-visibility.ts"
import type { CdpRequest, TargetInfo } from "./protocol.ts"
import { getString, isRestrictedTarget } from "./relay-helpers.ts"
import type { ChildTarget, ConnectedTarget } from "./relay-types.ts"
import { shouldExposeChildTarget, type TargetRegistry } from "./target-registry.ts"

const rootRoutableBrowserContextMethods = new Set([
  "Browser.grantPermissions",
  "Browser.resetPermissions",
  "Storage.getCookies",
  "Storage.setCookies",
  "Storage.clearCookies",
])

export function isRootRoutableBrowserContextMethod(method: string): boolean {
  return rootRoutableBrowserContextMethods.has(method)
}

export type CdpRoutedSession = {
  readonly tabId: number
  readonly rootSessionId: string
  readonly chromeSessionId?: string
}

export class CdpRouter<Client extends object> {
  constructor(
    private readonly clients: CdpClientPool<Client>,
    private readonly registry: TargetRegistry,
  ) {}

  canSeeTarget(client: Client, target: ConnectedTarget): boolean {
    return this.clients.has(client) && this.canSessionSeeTarget(this.clients.sessionId(client), target)
  }

  canSessionSeeTarget(clientSessionId: string | undefined, target: ConnectedTarget): boolean {
    return canClientSeeTarget({
      clientSessionId,
      targetOwnerSessionId: target.opencodeBrowserSessionId,
      targetOwner: target.owner,
      clientHasOwnedTarget: clientSessionId !== undefined && this.registry
        .listRootTargets()
        .some((candidate) => candidate.opencodeBrowserSessionId === clientSessionId),
    })
  }

  canSeeTab(client: Client, tabId: number): boolean {
    const rootTarget = this.registry.tabTargets.get(tabId)
    return rootTarget ? this.canSeeTarget(client, rootTarget) : false
  }

  preferredRoot(client: Client, browserContextId?: string): ConnectedTarget | undefined {
    const clientSessionId = this.clients.sessionId(client)
    const candidates = this.registry.listRootTargets().filter((target) => {
      if (target.crashed) return false
      if (browserContextId !== undefined && target.targetInfo.browserContextId !== browserContextId) return false
      return clientSessionId !== undefined
        ? target.opencodeBrowserSessionId === clientSessionId
        : this.canSeeTarget(client, target)
    })
    if (candidates.length === 0) return undefined
    if (clientSessionId !== undefined || candidates.length === 1) return candidates[0]
    const contexts = new Set(candidates.map((target) => target.targetInfo.browserContextId))
    // CDP omits browserContextId for the singleton default context. Matching
    // absence is therefore a validated default-context identity, not a guess.
    if (contexts.size === 1) {
      return candidates[0]
    }
    return undefined
  }

  isBrowserAlias(client: Client, sessionId: string): boolean {
    return ClientCdpSessionAlias.$is("Browser")(this.clients.alias(client, sessionId))
  }

  visibleRoots(client: Client): ConnectedTarget[] {
    return this.registry.listRootTargets().filter((target) => this.canSeeTarget(client, target))
  }

  rootForSession(client: Client, sessionId: string): ConnectedTarget | undefined {
    const target = this.registry.targets.get(sessionId)
    return target && this.canSeeTarget(client, target) ? target : undefined
  }

  targetForAttach(client: Client, targetId: string): ConnectedTarget | ChildTarget | undefined {
    const root = this.registry.targetsByTargetId.get(targetId)
    if (root) return this.canSeeTarget(client, root) ? root : undefined
    const child = this.registry.childTargetsByTargetId.get(targetId)
    return child && this.canSeeTab(client, child.tabId) ? child : undefined
  }

  targetInfo(client: Client, options: {
    readonly targetId?: string
    readonly sessionId?: string
  }): ConnectedTarget | ChildTarget | undefined {
    const alias = options.sessionId ? this.clients.alias(client, options.sessionId) : undefined
    const aliasedTargetId = ClientCdpSessionAlias.$is("Target")(alias) ? alias.targetId : undefined
    const target = (options.targetId
      ? this.registry.targetsByTargetId.get(options.targetId) ?? this.registry.childTargetsByTargetId.get(options.targetId)
      : undefined) ??
      (aliasedTargetId
        ? this.registry.targetsByTargetId.get(aliasedTargetId) ?? this.registry.childTargetsByTargetId.get(aliasedTargetId)
        : undefined) ??
      (options.sessionId
        ? this.registry.targets.get(options.sessionId) ?? this.registry.childTargets.get(options.sessionId)
        : undefined)
    if (!target) return undefined
    return "owner" in target
      ? this.canSeeTarget(client, target) ? target : undefined
      : this.canSeeTab(client, target.tabId) ? target : undefined
  }

  session(client: Client, requestedSessionId: string): CdpRoutedSession | undefined {
    const sessionAlias = this.clients.alias(client, requestedSessionId)
    if (ClientCdpSessionAlias.$is("Browser")(sessionAlias)) return undefined
    const alias = ClientCdpSessionAlias.$is("Target")(sessionAlias) ? sessionAlias : undefined
    const target = alias
      ? this.registry.targetsByTargetId.get(alias.targetId) ?? this.registry.childTargetsByTargetId.get(alias.targetId)
      : this.registry.targets.get(requestedSessionId) ?? this.registry.childTargets.get(requestedSessionId)
    if (!target || !this.canSeeTab(client, target.tabId)) return undefined
    const rootSessionId = this.registry.tabTargets.get(target.tabId)?.sessionId
    if (!rootSessionId) return undefined
    const expectedChromeSessionId = "owner" in target ? undefined : target.sessionId
    if (alias && (alias.tabId !== target.tabId || alias.chromeSessionId !== expectedChromeSessionId)) return undefined
    return {
      tabId: target.tabId,
      rootSessionId,
      ...(expectedChromeSessionId ? { chromeSessionId: expectedChromeSessionId } : {}),
    }
  }

  resolveCommandRoute(client: Client, message: CdpRequest): CdpRoutedSession {
    const browserAlias = message.sessionId !== undefined && this.isBrowserAlias(client, message.sessionId)
    const rootRoutable = isRootRoutableBrowserContextMethod(message.method) && (!message.sessionId || browserAlias)
    const requestedBrowserContextId = getString(message.params, "browserContextId")
    const preferredRoot = rootRoutable ? this.preferredRoot(client, requestedBrowserContextId) : undefined
    const route = rootRoutable && preferredRoot
      ? { tabId: preferredRoot.tabId, rootSessionId: preferredRoot.sessionId }
      : message.sessionId
      ? this.session(client, message.sessionId)
      : undefined
    if (route) return route
    throw new Error(rootRoutable
      ? requestedBrowserContextId !== undefined
        ? `A healthy visible root target in browser context ${requestedBrowserContextId} is required for ${message.method}`
        : this.clients.sessionId(client) === undefined
        ? `Exactly one visible browser context is required for ${message.method}`
        : `A healthy session-owned root target is required for ${message.method}`
      : message.sessionId
      ? `Unknown CDP session ${message.sessionId} for ${message.method}`
      : `CDP sessionId is required for ${message.method}`)
  }

  reconcileClient(client: Client): void {
    this.clients.pruneInvisible(client, (tabId) => this.canSeeTab(client, tabId))
  }

  visibleTargetInfos(client: Client): TargetInfo[] {
    return this.registry.allTargetInfos({
      isRestrictedTarget,
      isVisibleTarget: (target) => {
        return this.canSeeTab(client, target.tabId) && ("owner" in target || shouldExposeChildTarget(target))
      },
    })
  }
}

import type { WebSocket } from "ws"
import type { CdpRequest, JsonObject, TargetInfo } from "./protocol.ts"
import { getObject, getString, sendCdpEvent } from "./relay-helpers.ts"
import type { ChildTarget } from "./relay-types.ts"
import { shouldExposeChildTarget, type TargetRegistry } from "./target-registry.ts"
import type { CdpClientPool } from "./cdp-client-pool.ts"

// Patchright sends Emulation.setEmulatedMedia with its own defaults for these features on every page
// (light, no-preference, none, no-preference), which hides the user's real settings from the page and makes
// matchMedia disagree with the rest of the browser. execute marks overrides the agent asked for with
// __bc_explicit__; values other than the defaults can only come from the agent.
const patchrightDefaultMediaFeatures: ReadonlyMap<string, string> = new Map([
  ["prefers-color-scheme", "light"],
  ["prefers-reduced-motion", "no-preference"],
  ["forced-colors", "none"],
  ["prefers-contrast", "no-preference"],
])

/** Drops Patchright's default media feature overrides unless the agent asked for them. */
export function removeDefaultLightColorSchemeEmulation(message: CdpRequest): CdpRequest {
  if (message.method !== "Emulation.setEmulatedMedia") {
    return message
  }
  const features = Array.isArray(message.params?.features) ? message.params.features : []
  const isExplicit = features.some((feature) => {
    const object = getObject(feature)
    return object?.name === "__bc_explicit__"
  })
  const kept = features.filter((feature) => {
    const object = getObject(feature)
    if (object?.name === "__bc_explicit__") return false
    if (isExplicit) return true
    const name = getString(object, "name")
    return name === undefined || patchrightDefaultMediaFeatures.get(name) !== object?.value
  })
  if (kept.length === features.length) {
    return message
  }
  return {
    ...message,
    params: {
      ...message.params,
      features: kept,
    },
  }
}

export function replayChildTargetsForParent<Client extends Pick<WebSocket, "send">>(options: {
  readonly socket: Client
  readonly parentSessionId: string
  readonly registry: TargetRegistry
  readonly clients: CdpClientPool<Client>
}): void {
  for (const target of options.registry.childTargets.values()) {
    if (target.parentSessionId === options.parentSessionId && shouldExposeChildTarget(target)) {
      replayFrameEventsForChild({ socket: options.socket, registry: options.registry, target })
      options.clients.announce(options.socket, target)
      replayChildFrameNavigation({ socket: options.socket, registry: options.registry, target })
    }
  }
}

function replayFrameEventsForChild(options: { readonly socket: Pick<WebSocket, "send">; readonly registry: TargetRegistry; readonly target: ChildTarget }): void {
  if (options.target.targetInfo.type !== "iframe") {
    return
  }
  const frameEvents = options.registry.tabFrameEvents.get(options.target.tabId)?.get(options.target.targetInfo.targetId)
  if (!frameEvents) {
    return
  }
  if (frameEvents.attached) {
    sendCdpEvent(options.socket, { sessionId: options.target.parentSessionId, method: "Page.frameAttached", params: frameEvents.attached })
  }
  if (frameEvents.navigated) {
    sendCdpEvent(options.socket, { sessionId: options.target.parentSessionId, method: "Page.frameNavigated", params: frameEvents.navigated })
  }
}

export function replayChildFrameNavigation(options: { readonly socket: Pick<WebSocket, "send">; readonly registry: TargetRegistry; readonly target: ChildTarget }): void {
  const navigationParams = childFrameNavigationParams({ registry: options.registry, target: options.target })
  if (!navigationParams) {
    return
  }
  // Stock Playwright does not apply Page.getFrameTree to child iframe sessions;
  // replay the current navigation on the child session so reconnects do not
  // leave OOPIF frames with an empty URL.
  sendCdpEvent(options.socket, { sessionId: options.target.sessionId, method: "Page.frameNavigated", params: navigationParams })
}

function childFrameNavigationParams(options: { readonly registry: TargetRegistry; readonly target: ChildTarget }): JsonObject | undefined {
  if (options.target.targetInfo.type !== "iframe") {
    return undefined
  }
  const frameEvents = options.registry.findFrameEventsForChild(options.target)
  const navigated = frameEvents?.navigated
  const frame = getObject(navigated?.frame)
  if (navigated && frame) {
    return {
      ...navigated,
      frame: {
        ...frame,
        id: options.target.targetInfo.targetId,
        url: options.target.targetInfo.url || (getString(frame, "url") ?? ""),
        ...(options.target.targetInfo.parentFrameId ? { parentId: options.target.targetInfo.parentFrameId } : {}),
      },
    }
  }
  if (!options.target.targetInfo.url) {
    return undefined
  }
  const gatedAPIFeatures: string[] = []
  return {
    frame: {
      id: options.target.targetInfo.targetId,
      loaderId: options.target.targetInfo.targetId,
      url: options.target.targetInfo.url,
      domainAndRegistry: "",
      securityOrigin: new URL(options.target.targetInfo.url).origin,
      mimeType: "text/html",
      adFrameStatus: { adFrameType: "none" },
      secureContextType: "Secure",
      crossOriginIsolatedContextType: "NotIsolated",
      gatedAPIFeatures,
      ...(options.target.targetInfo.parentFrameId ? { parentId: options.target.targetInfo.parentFrameId } : {}),
    },
  }
}

export function replayTargetCreated(options: { readonly socket: Pick<WebSocket, "send">; readonly targetInfos: readonly TargetInfo[] }): void {
  for (const targetInfo of options.targetInfos) {
    sendCdpEvent(options.socket, { method: "Target.targetCreated", params: { targetInfo } })
  }
}

/**
 * Per-session domain allowlists, and the origin patterns secrets declare.
 *
 * A session can be given a list of allowed hosts (opt-in; sessions without one may go anywhere, because localhost dev
 * servers are a core use). With a list, the relay refuses agent navigations to other hosts (Page.navigate,
 * Target.createTarget) and sends session tabs that end up elsewhere anyway (a link, a redirect, a script's
 * location change, a popup) back to about:blank, or closes the popup.
 *
 * Pattern forms (case-insensitive):
 *
 * - `example.com`: that host, http or https, any port. `example.com:8443`: that host and port.
 * - `*.example.com`: example.com and every subdomain.
 * - `https://example.com`, `http://localhost:3000`, `https://*.example.com`: scheme, host and port must match.
 * - IP literals: `127.0.0.1`, `[::1]`, `10.0.0.5:8080`.
 *
 * Private, loopback, link-local and other non-public addresses (and `localhost`) are refused even when a wildcard
 * matches them; only a pattern naming that exact host allows one. Hostnames are resolved before an agent navigation
 * and the document's actual remote IP is checked when it arrives, so a public name that resolves to (or rebinds to) a
 * private address is caught too. URLs are parsed the WHATWG way, so decimal, octal or hex IPv4 spellings normalize to
 * dotted form before the check.
 *
 * Pure module apart from `resolvesToPrivateAddress` (DNS).
 */
import dns from "node:dns/promises"
import net from "node:net"

export type OriginRule = {
  readonly pattern: string
  readonly scheme?: "http:" | "https:"
  /** Lowercase host without brackets; for wildcards, the suffix after `*.`. */
  readonly host: string
  readonly wildcard: boolean
  readonly port?: string
}

export class OriginPatternError extends Error {
  override readonly name = "OriginPatternError"
}

const maxPatterns = 100

export function parseOriginPattern(raw: string): OriginRule {
  const pattern = raw.trim()
  if (!pattern) throw new OriginPatternError("Empty origin pattern")
  if (pattern === "*" || pattern === "*.*") throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)} allows every site; leave the allowlist unset instead`)
  const schemeMatch = /^([a-z][a-z0-9+.-]*):\/\//i.exec(pattern)
  const scheme = schemeMatch?.[1]?.toLowerCase()
  if (scheme !== undefined && scheme !== "http" && scheme !== "https") {
    throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)}: only http and https origins can be allowed`)
  }
  let rest = schemeMatch ? pattern.slice(schemeMatch[0].length) : pattern
  if (/[/?#]/.test(rest.replace(/\/$/, ""))) throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)} must be a host or origin, without a path`)
  rest = rest.replace(/\/$/, "")
  const wildcard = rest.startsWith("*.")
  if (wildcard) rest = rest.slice(2)
  if (rest.includes("*")) throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)}: a wildcard is only allowed as a leading "*."`)
  let parsed: URL
  try {
    parsed = new URL(`${scheme ?? "http"}://${rest}`)
  } catch {
    throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)} is not a valid host or origin`)
  }
  if (parsed.username || parsed.password || parsed.pathname !== "/" || parsed.search || parsed.hash || !parsed.hostname) {
    throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)} must be a host or origin`)
  }
  const host = unbracket(parsed.hostname.toLowerCase())
  if (wildcard && net.isIP(host)) throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)}: wildcards don't apply to IP addresses`)
  if (wildcard && !host.includes(".")) throw new OriginPatternError(`Origin pattern ${JSON.stringify(raw)}: "*." needs a domain with a dot, like *.example.com`)
  // An origin with a scheme and no port means the scheme's default port; a bare host means any port.
  const port = parsed.port || (scheme ? (scheme === "https" ? "443" : "80") : undefined)
  return {
    pattern,
    ...(scheme ? { scheme: `${scheme}:` as const } : {}),
    host,
    wildcard,
    ...(port ? { port } : {}),
  }
}

export function parseOriginPatterns(raw: readonly string[]): readonly OriginRule[] {
  if (raw.length > maxPatterns) throw new OriginPatternError(`At most ${maxPatterns} origin patterns are allowed`)
  return raw.map(parseOriginPattern)
}

/** Normalized pattern strings, for storage and display. Throws OriginPatternError on an invalid one. */
export function normalizeOriginPatterns(raw: readonly string[]): readonly string[] {
  return Array.from(new Set(parseOriginPatterns(raw.flatMap((entry) => entry.split(",")).map((entry) => entry.trim()).filter(Boolean)).map((rule) => rule.pattern.toLowerCase())))
}

function unbracket(host: string): string {
  return host.startsWith("[") && host.endsWith("]") ? host.slice(1, -1) : host
}

function ipv4ToNumber(ip: string): number {
  return ip.split(".").reduce((value, part) => value * 256 + Number(part), 0)
}

const privateIpv4Ranges: ReadonlyArray<readonly [string, number]> = [
  ["0.0.0.0", 8], ["10.0.0.0", 8], ["100.64.0.0", 10], ["127.0.0.0", 8], ["169.254.0.0", 16], ["172.16.0.0", 12],
  ["192.0.0.0", 24], ["192.0.2.0", 24], ["192.168.0.0", 16], ["198.18.0.0", 15], ["198.51.100.0", 24],
  ["203.0.113.0", 24], ["224.0.0.0", 4], ["240.0.0.0", 4],
]

/** True for loopback, private, link-local, CGNAT, documentation, multicast and reserved addresses. */
export function isPrivateAddress(address: string): boolean {
  const ip = unbracket(address.toLowerCase()).replace(/%.*$/, "")
  if (net.isIPv4(ip)) {
    const value = ipv4ToNumber(ip)
    return privateIpv4Ranges.some(([base, bits]) => {
      const mask = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0
      return ((value & mask) >>> 0) === ((ipv4ToNumber(base) & mask) >>> 0)
    })
  }
  if (net.isIPv6(ip)) {
    if (ip === "::" || ip === "::1") return true
    const mapped = /^(?:0*:)*:?ffff:(\d+\.\d+\.\d+\.\d+)$/.exec(ip) ?? /^::(\d+\.\d+\.\d+\.\d+)$/.exec(ip)
    if (mapped?.[1]) return isPrivateAddress(mapped[1])
    const hexMapped = /^::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})$/.exec(ip)
    if (hexMapped?.[1] && hexMapped[2]) {
      const high = parseInt(hexMapped[1], 16)
      const low = parseInt(hexMapped[2], 16)
      return isPrivateAddress(`${high >> 8}.${high & 255}.${low >> 8}.${low & 255}`)
    }
    const first = parseInt(ip.split(":")[0] || "0", 16)
    // fc00::/7 unique local, fe80::/10 link-local, ff00::/8 multicast, 64:ff9b::/96 NAT64 (embeds IPv4).
    if ((first & 0xfe00) === 0xfc00 || (first & 0xffc0) === 0xfe80 || (first & 0xff00) === 0xff00) return true
    if (ip.startsWith("64:ff9b::")) return true
    return false
  }
  return false
}

function isLocalhostName(host: string): boolean {
  return host === "localhost" || host.endsWith(".localhost") || host === "localhost.localdomain"
}

/** Whether a host is non-public by its spelling alone (IP literal or localhost name). */
export function isPrivateHost(host: string): boolean {
  const bare = unbracket(host.toLowerCase())
  return isLocalhostName(bare) || (net.isIP(bare) !== 0 && isPrivateAddress(bare))
}

function defaultPort(protocol: string): string {
  return protocol === "https:" ? "443" : "80"
}

function ruleMatches(rule: OriginRule, url: URL, host: string, options: { readonly httpsOnlyWithoutScheme?: boolean }): boolean {
  if (rule.scheme !== undefined && rule.scheme !== url.protocol) return false
  if (rule.scheme === undefined && options.httpsOnlyWithoutScheme && url.protocol !== "https:" && !isPrivateHost(host)) return false
  if (rule.port !== undefined && rule.port !== (url.port || defaultPort(url.protocol))) return false
  if (rule.wildcard) return host === rule.host || host.endsWith(`.${rule.host}`)
  return host === rule.host
}

/** A rule that names this exact host (no wildcard): the only kind that allows a private address. */
export function explicitlyAllowsHost(rules: readonly OriginRule[], url: string): boolean {
  try {
    const parsed = new URL(url)
    const host = unbracket(parsed.hostname.toLowerCase())
    return rules.some((rule) => !rule.wildcard && ruleMatches(rule, parsed, host, {}))
  } catch {
    return false
  }
}

export type UrlDecision =
  | { readonly allowed: true; readonly host?: string; readonly explicit?: boolean }
  | { readonly allowed: false; readonly reason: string }

/** Schemes that load no remote document: about:blank and srcdoc, data: (an opaque origin), blob: (the creator's). */
const neutralSchemes = new Set(["about:", "data:", "blob:"])

/**
 * Check a URL against allowed origin patterns (synchronously: by spelling, without DNS).
 * `httpsOnlyWithoutScheme` makes bare-host patterns match https only (used for secrets), except for local hosts.
 */
export function checkUrl(rawUrl: string, rules: readonly OriginRule[], options: { readonly httpsOnlyWithoutScheme?: boolean } = {}): UrlDecision {
  let url: URL
  try {
    url = new URL(rawUrl)
  } catch {
    return { allowed: false, reason: `${JSON.stringify(rawUrl.slice(0, 200))} is not a valid URL` }
  }
  if (neutralSchemes.has(url.protocol)) return { allowed: true }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    return { allowed: false, reason: `${url.protocol} URLs are not allowed for this session` }
  }
  const host = unbracket(url.hostname.toLowerCase())
  const matching = rules.filter((rule) => ruleMatches(rule, url, host, options))
  if (matching.length === 0) {
    return { allowed: false, reason: `${url.host} is not in the allowed origins (${rules.map((rule) => rule.pattern).join(", ") || "none"})` }
  }
  const explicit = matching.some((rule) => !rule.wildcard)
  if (isPrivateHost(host) && !explicit) {
    return { allowed: false, reason: `${url.host} is a private, loopback or local address; allow it by naming that exact host` }
  }
  return { allowed: true, host, explicit }
}

/** Resolve a hostname and report a non-public address it resolves to, or undefined (also when DNS fails). */
export async function resolvesToPrivateAddress(host: string, timeoutMs = 2_000): Promise<string | undefined> {
  const bare = unbracket(host)
  if (net.isIP(bare) || isLocalhostName(bare)) return isPrivateHost(bare) ? bare : undefined
  let timer: ReturnType<typeof setTimeout> | undefined
  try {
    const addresses = await Promise.race([
      dns.lookup(bare, { all: true, verbatim: true }),
      new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new Error("DNS lookup timed out")), timeoutMs) }),
    ])
    return addresses.find((entry) => isPrivateAddress(entry.address))?.address
  } catch {
    return undefined
  } finally {
    if (timer) clearTimeout(timer)
  }
}

/** Full check for an agent navigation: spelling, then DNS for names an explicit pattern doesn't cover. */
export async function checkNavigationUrl(rawUrl: string, rules: readonly OriginRule[]): Promise<UrlDecision> {
  const decision = checkUrl(rawUrl, rules)
  if (!decision.allowed || decision.host === undefined || decision.explicit) return decision
  const privateAddress = await resolvesToPrivateAddress(decision.host)
  if (privateAddress) {
    return { allowed: false, reason: `${decision.host} resolves to the private address ${privateAddress}; allow it by naming that exact host` }
  }
  return decision
}

import crypto from "node:crypto"
import { Predicate } from "effect"
import { PageReadTimeoutError } from "./page-read-timeout.ts"
import { getIdText, getString } from "./relay-helpers.ts"
import type { ExecuteAftermath } from "./relay-schema.ts"
import type { JsonObject } from "./protocol.ts"

export type RuntimeFailureKind = "context-destroyed" | "context-missing" | "cross-extension-page" | "target-closed" | "timeout" | "other"

const maxDiagnosticTokenLength = 48

export function runtimeFailureKind(cause: unknown): RuntimeFailureKind {
  for (const message of errorMessages(cause)) {
    if (/cannot access a chrome-extension:\/\/ url of different extension/i.test(message)) {
      return "cross-extension-page"
    }
    if (/execution context was destroyed|context.*destroyed/i.test(message)) {
      return "context-destroyed"
    }
    if (/cannot find context with (?:specified )?id|execution context.*(?:not found|not available|does not exist)|context.*detached frame|frame (?:was|got) detached/i.test(message)) {
      return "context-missing"
    }
    if (/target page, context or browser has been closed|target closed|session closed/i.test(message)) {
      return "target-closed"
    }
    if (/timed out|timeout/i.test(message)) {
      return "timeout"
    }
  }
  return "other"
}

export function executionContextFailureDiagnostic(cause: unknown, aftermath: ExecuteAftermath | undefined): string | undefined {
  const kind = runtimeFailureKind(cause)
  if (kind === "cross-extension-page") {
    return "target/cross-extension-page"
  }
  for (const error of errorCauses(cause)) {
    if (error instanceof PageReadTimeoutError) {
      // This is read-deadline evidence, not a lost context requiring page recovery.
      return `session-page/context-read-timeout; operation=${error.operation}; timeoutMs=${error.timeoutMs}`
    }
  }
  if (kind !== "context-destroyed" && kind !== "context-missing") {
    return undefined
  }
  const pageClosed = aftermath?.endUrl === null
  const urlChanged = aftermath ? aftermath.startUrl !== aftermath.endUrl : false
  const navigationCount = aftermath?.navigations.length ?? 0
  return `execution-context/${kind}; pageClosed=${pageClosed}; urlChanged=${urlChanged}; mainFrameNavigations=${navigationCount}`
}

export function summarizeDiagnosticUrl(value: string | undefined): string {
  if (!value) {
    return "url=none"
  }
  const fingerprint = crypto.createHash("sha256").update(value).digest("hex").slice(0, 12)
  try {
    const parsed = new URL(value)
    const pathSegments = parsed.pathname.split("/").filter(Boolean).length
    const origin = parsed.origin === "null" ? `${parsed.protocol}//` : parsed.origin
    return `origin=${boundedToken(origin)} pathSegments=${pathSegments} query=${parsed.search ? "yes" : "no"} fragment=${parsed.hash ? "yes" : "no"} urlHash=${fingerprint}`
  } catch {
    return `url=unparseable chars=${value.length} urlHash=${fingerprint}`
  }
}

export function summarizeRuntimeEvaluate(params: JsonObject | undefined): string {
  const source = getString(params, "expression") ?? getString(params, "functionDeclaration")
  const sourceLength = source?.length ?? 0
  const rawContextId = getIdText(params, "contextId") ?? getIdText(params, "executionContextId")
  const contextId = rawContextId !== undefined ? boundedToken(rawContextId) : "default"
  return [
    `sourceChars=${sourceLength}`,
    `argumentCount=${Array.isArray(params?.arguments) ? params.arguments.length : 0}`,
    `context=${contextId}`,
    `awaitPromise=${params?.awaitPromise === true}`,
    `returnByValue=${params?.returnByValue === true}`,
    `userGesture=${params?.userGesture === true}`,
  ].join(" ")
}

export function boundedToken(value: string | undefined): string {
  if (!value) {
    return "none"
  }
  const normalized = value.replace(/[^a-zA-Z0-9:._/-]/g, "_")
  if (normalized.length <= maxDiagnosticTokenLength) {
    return normalized
  }
  return `${normalized.slice(0, maxDiagnosticTokenLength - 9)}~${crypto.createHash("sha256").update(value).digest("hex").slice(0, 8)}`
}

function errorMessages(cause: unknown): string[] {
  return errorCauses(cause).flatMap((error) => error instanceof Error ? [error.message] : Predicate.isString(error) ? [error] : [])
}

function errorCauses(cause: unknown): unknown[] {
  const causes: unknown[] = []
  const seen = new Set<unknown>()
  let current = cause
  for (let depth = 0; depth < 5 && current !== undefined && current !== null && !seen.has(current); depth++) {
    seen.add(current)
    causes.push(current)
    if (current instanceof Error) {
      current = current.cause
      continue
    }
    break
  }
  return causes
}

// Service worker: keeps the link to the local browse relay (agent-relay.ts), which drives tabs for agents. The
// toolbar button lets agents use the current tab, or stops them; the status page (welcome.html, also the options
// page) shows the connection.
import { AGENT_DIAGNOSTICS, STATUS_PORT, type FromStatusPage, type ToStatusPage } from "../shared/protocol"
import { createAgentRelay } from "./agent-relay"
import { TabCleanup } from "./tab-cleanup"

// Neutral by default; amber while an agent runs, blue while it waits for the user.
const BADGE_COLORS: Record<string, string> = { default: "#3b3b3b", RUN: "#b45309", WAIT: "#2563eb" }
const pages = new Set<chrome.runtime.Port>()
const agents = createAgentRelay({
  changed: (state) => broadcast({ type: "agents", state }),
  badgesChanged: () => void updateBadges(),
})

chrome.action.onClicked.addListener((tab) => {
  if (tab.id !== undefined) agents.attachTab(tab.id)
})

declare const __OPENCODE_BROWSER_TEST_HOOKS__: boolean
// Test builds only (OPENCODE_BROWSER_TEST_HOOKS=1 when building): the stress harness clicks the toolbar button through
// this worker's DevTools target, as CDP can't click browser UI. Pages can't reach the worker's globals, and other
// builds compile this out.
if (__OPENCODE_BROWSER_TEST_HOOKS__)
  Object.assign(globalThis, { __opencodeBrowserTest: { toolbarClick: (tabId: number) => agents.attachTab(tabId) } })

chrome.runtime.onConnect.addListener((port) => {
  if (port.name !== STATUS_PORT || port.sender?.id !== chrome.runtime.id) return
  pages.add(port)
  port.onDisconnect.addListener(() => pages.delete(port))
  port.onMessage.addListener((message: FromStatusPage) => {
    if (message.type === "agents.reconnect") agents.reconnect()
    if (message.type === "tabs.cleanup") void TabCleanup.cleanup({ minutes: 0 })
    if (message.type === "autoUpdate.set") agents.setAutoUpdate(message.mode)
    if (message.type === "pairing.ticket") post(port, { type: "pairing.ticket.result", ok: agents.pairTicket(message.ticket) })
    if (message.type === "pairing.set")
      void agents.pair(message.code).then((ok) => post(port, { type: "pairing.result", ok }))
  })
  post(port, { type: "agents", state: agents.state() })
})

// Content scripts (page status, handoffs) and the recording document talk to the relay link; extension pages ask
// it for diagnostics.
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  const relay = agents.runtimeMessage(message, sender, sendResponse)
  if (relay !== undefined) return relay
  const page = sender.id === chrome.runtime.id && sender.url?.startsWith(`chrome-extension://${chrome.runtime.id}/`)
  if (!page || typeof message !== "object" || message?.action !== AGENT_DIAGNOSTICS) return false
  void agents.diagnostics().then(
    (text) => sendResponse({ text }),
    (error: unknown) => sendResponse({ text: `Diagnostics failed: ${String(error)}` }),
  )
  return true
})

chrome.runtime.onInstalled.addListener((details) => {
  if (details.reason === "install") void chrome.tabs.create({ url: chrome.runtime.getURL("welcome.html") })
})

// Tab-specific badges reset when a tab navigates; the relay's state for it doesn't.
chrome.tabs.onUpdated.addListener((_tabId, change, tab) => {
  if (change.url || change.status === "loading") void updateBadges([tab])
})

void chrome.action.setBadgeBackgroundColor({ color: BADGE_COLORS.default })
void chrome.action.setBadgeTextColor?.({ color: "#ffffff" })

/** The toolbar badge shows the agents' state for a tab they use: ON, RUN while one works, WAIT for the user. */
async function updateBadges(tabs?: chrome.tabs.Tab[]) {
  const targets = tabs ?? (await chrome.tabs.query({}))
  await Promise.all(
    targets.map(async (tab) => {
      if (tab.id === undefined) return
      const badge = agents.badge(tab.id)
      await chrome.action.setBadgeText({ tabId: tab.id, text: badge?.text ?? "" }).catch(() => undefined)
      await chrome.action
        .setBadgeBackgroundColor({ tabId: tab.id, color: BADGE_COLORS[badge?.text ?? ""] ?? BADGE_COLORS.default })
        .catch(() => undefined)
      await chrome.action
        .setTitle({ tabId: tab.id, title: badge?.title ?? "Browse · Click to let agents use this tab" })
        .catch(() => undefined)
    }),
  )
}

function broadcast(message: ToStatusPage) {
  pages.forEach((port) => post(port, message))
}

function post(port: chrome.runtime.Port, message: ToStatusPage) {
  try {
    port.postMessage(message)
  } catch {
    pages.delete(port)
  }
}
